INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 7, 'page_content', 'live', '{"h1":"Tourist Police-Led Private Volcano Tours in East Java","sections":[{"id":"differentiators","title":"What makes JVTO different","bullets":["Led by an active Tourist Police officer — safety is the operator, not a policy document","Licensed by the Indonesian government: TDUP, NIB, business license","Health screening before every Ijen night trek — mandatory, not optional","All tours are private — your group, your schedule, your vehicle","Verified on Tripadvisor, Trustpilot, ISIC, and Indecon","Based in Bondowoso — 45 minutes from Ijen Crater, daily operations since 2015"]},{"id":"destinations-summary","items":[{"name":"Mount Bromo","route":"/destinations/mount-bromo","highlight":"Sunrise over Tengger Caldera"},{"name":"Kawah Ijen","route":"/destinations/ijen-crater","highlight":"Blue fire phenomenon, acidic crater lake"},{"name":"Tumpak Sewu Waterfall","route":"/destinations/tumpak-sewu-waterfall","highlight":"Thousand-stream waterfall, Semeru backdrop"},{"name":"Madakaripura Waterfall","route":"/destinations/madakaripura-waterfall","highlight":"Sacred 200m canyon waterfall"},{"name":"Papuma Beach","route":"/destinations/papuma-beach","highlight":"White sand beach with rock formations, Jember"}],"title":"Destinations"},{"id":"tours-summary","title":"Browse tours","bullets":["From Surabaya (1D to 6D): /tours/from-surabaya","From Bali (3D to 5D): /tours/from-bali","All tours: /tours"]},{"id":"trust-signals","title":"Verified presence","bullets":["Tripadvisor: tripadvisor.com/Attraction_Review-g297715-d19983165","Trustpilot: trustpilot.com/review/javavolcano-touroperator.com","ISIC partner: isic.org/discounts/?providerId=259268","Indecon: indecon.id/spotlight-networks/java-volcano-tour-operator","Google Maps: google.com/maps?cid=1266403973589689021"]},{"id":"verify-cta","title":"Verify independently","paragraphs":["Every claim links to a verifiable source. Full proof library at /verify-jvto."]}],"cross_links":{"tours":"/tours","verify":"/verify-jvto","contact":"/contact","why_jvto":"/why-jvto","destinations":"/destinations","travel_guide":"/travel-guide"},"intro_paragraphs":["Java Volcano Tour Operator (JVTO) is a registered Indonesian travel company based in Bondowoso and led by an active Tourist Police officer. We design private, all-inclusive itineraries to Mount Bromo, Ijen Crater and Tumpak Sewu with clear safety rules, transparent pricing and real local impact.","All tours are private — no shared buses. Every package includes transport, accommodation, permits, English-speaking guides, and meals as stated. Health screening is conducted the evening before the Ijen night trek.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."]}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/';
