INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 4, 'page_content', 'design-system', '{"h1":"JVTO Private Volcano Tours","body_md":"# JVTO Private Volcano Tours\n\nChoose a private, all-inclusive East Java volcano tour by starting point.\n\n## From Surabaya\n- [1D1N Bromo Midnight](/tours/from-surabaya/bromo-1d1n) — from IDR 1,000,000 per person\n- [2D1N Bromo Sunrise + Madakaripura](/tours/from-surabaya/bromo-2d1n) — from IDR 1,750,000 per person\n- [3D2N Bromo + Madakaripura + Ijen (Surabaya–Bali overland)](/tours/from-surabaya/bromo-madakaripura-ijen-3d2n) — from IDR 2,450,000 per person\n- [2D1N Ijen Blue Fire Expedition](/tours/from-surabaya/ijen-2d1n) — from IDR 1,550,000 per person\n- [3D2N Ijen + Bromo + Madakaripura (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-3d2n) — from IDR 2,450,000 per person\n- [4D3N Ijen + Bromo + Madakaripura Expedition (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-4d3n) — from IDR 3,025,000 per person\n- [5D4N Ijen + Bromo + Madakaripura + Malang (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-malang-5d4n) — from IDR 3,850,000 per person\n- [4D3N Ijen + Papuma + Tumpak Sewu + Bromo (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-4d3n) — from IDR 3,125,000 per person\n- [5D4N Full East Java Circuit (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-5d4n) — from IDR 3,650,000 per person\n- [6D5N Grand East Java (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-malang-6d5n) — from IDR 4,750,000 per person\n- [3D2N Taman Safari Prigen + Bromo + Madakaripura (Specialty)](/tours/from-surabaya/taman-safari-prigen-bromo-madakaripura-3d2n) — from IDR 3,450,000 per person\n- [4D3N Tumpak Sewu + Bromo + Ijen (Surabaya–Bali overland)](/tours/from-surabaya/tumpak-sewu-bromo-ijen-4d3n) — from IDR 3,125,000 per person\n\n## From Bali\n- [3D2N Bromo + Ijen (Bali–Bali)](/tours/from-bali/bromo-ijen-3d2n) — from IDR 2,850,000 per person\n- [3D2N Ijen + Bromo + Madakaripura (Bali–Surabaya)](/tours/from-bali/ijen-bromo-madakaripura-3d2n) — from IDR 2,850,000 per person\n- [4D3N Full Circuit (Bali–Surabaya)](/tours/from-bali/ijen-papuma-tumpak-sewu-bromo-4d3n) — from IDR 3,475,000 per person\n- [5D4N Full Circuit Extended (Bali–Surabaya)](/tours/from-bali/ijen-papuma-tumpak-sewu-bromo-5d4n) — from IDR 4,050,000 per person","schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours';
