INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'card_grid', 'tour', '{}'::jsonb, ARRAY['package:surabaya-bromo-1d1n','package:surabaya-bromo-2d1n','package:surabaya-bromo-madakaripura-ijen-3d2n','package:surabaya-ijen-2d1n','package:surabaya-ijen-bromo-madakaripura-3d2n','package:surabaya-ijen-bromo-madakaripura-4d3n','package:surabaya-ijen-bromo-madakaripura-malang-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-4d3n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-malang-6d5n','package:surabaya-taman-safari-prigen-bromo-madakaripura-3d2n','package:surabaya-tumpak-sewu-bromo-ijen-4d3n']::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-surabaya';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'design-system', '{"h1":"Surabaya Landing Page — Website Copy","body_md":"# Surabaya Landing Page — Website Copy\n\n---\n\n## Hero Section\n\n### H1\nPrivate Volcano Tours from Surabaya — Police-Led, All-Inclusive, Zero Hidden Costs\n\n### Subheadline\n11 private packages: Kawah Ijen, Mount Bromo, Tumpak Sewu & Madakaripura. Your own vehicle. Your own crew. Led by an active Tourist Police officer.\n\n### Credibility Line\nLicensed operator NIB 1102230032918 · Trustpilot 4.8/5 (51 reviews) · Founded 2015\n\n---\n\n## Lead Paragraph\n\nEvery JVTO tour from Surabaya is 100% private — your group, your vehicle, your schedule. Mr. Sam, the founder, is an active officer of the Indonesian Tourist Police (Ditpamobvit East Java): every route, safety decision, and written rule traces back to someone who answers to police protocol. What''s included is written before you book. What it costs is confirmed before you pay.\n\n---\n\n## Package Section\n\n### Section Heading\n11 Private Tours from Surabaya\n\nAll packages: dedicated vehicle, English-speaking crew, entrance fees, accommodation + breakfast, mineral water, JVTO T-shirt. Price per person — no hidden local payments.\n\n---\n\n#### 1-Day Package\n\n**1 Day Bromo Midnight Experience**\nDepart Surabaya after midnight. Penanjakan sunrise point, Bromo crater rim by morning, return Surabaya same day. Private 4WD Jeep for the crater area included.\n*From IDR 1,550,000/person (2 pax) · IDR 1,000,000/person (11+ pax)*\n\n---\n\n#### 2-Day Packages\n\n**2 Day Bromo Sunrise Adventure**\nPenanjakan sunrise, Bromo crater, Madakaripura Waterfall — the tallest waterfall in Java — in two days. Return to Surabaya on Day 2.\n*From IDR 2,800,000/person (2 pax) · IDR 1,750,000/person (11+ pax)*\n\n**2 Day Ijen Blue Fire Expedition**\nNight hike to Kawah Ijen Crater. Blue Fire is a natural phenomenon subject to weather and gas activity — visibility depends on conditions at the time of your hike. Gas masks and trekking poles provided by JVTO. A health certificate is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024; JVTO coordinates clinic workflow for every guest under BBKSDA SE.1658/KSA.9/2024.\n*From IDR 2,300,000/person (2 pax) · IDR 1,550,000/person (11+ pax)*\n\n---\n\n#### 3-Day Packages\n\n**3 Day Ijen, Bromo & Madakaripura — Surabaya Return**\nKawah Ijen night hike (Day 1–2), Mount Bromo sunrise and crater (Day 2–3), Madakaripura Waterfall canyon (Day 3). Ends back in Surabaya.\n*From IDR 3,570,000/person (2 pax) · IDR 2,450,000/person (11+ pax)*\n\n**3 Day Bromo, Madakaripura & Ijen Overland — Surabaya to Bali**\nBromo sunrise, Madakaripura canyon, Ijen crater — finishing in Bali (ferry crossing Gilimanuk–Ketapang included). One-way Surabaya–Bali overland.\n*From IDR 3,570,000/person (2 pax) · IDR 2,450,000/person (11+ pax)*\n\n---\n\n#### 4-Day Packages\n\n**4 Day Ijen, Bromo & Madakaripura Expedition — Surabaya Return**\nExtended version of the 3D2N route. Additional time buffer for Bromo caldera and Madakaripura approach.\n*From IDR 4,450,000/person (2 pax) · IDR 3,025,000/person (11+ pax)*\n\n**4 Day Ijen, Papuma Beach, Tumpak Sewu & Bromo Journey — Surabaya Return**\nFour destinations: Kawah Ijen crater, Papuma Beach coastal break (Jember), Tumpak Sewu curtain waterfall (~120 m), Mount Bromo sunrise. Ends Surabaya.\n*From IDR 4,550,000/person (2 pax) · IDR 3,125,000/person (11+ pax)*\n\n**4 Day Tumpak Sewu, Bromo & Ijen Adventure — Surabaya to Bali**\nSame four-destination circuit as above, finishing in Bali with Gilimanuk–Ketapang ferry included.\n*From IDR 4,550,000/person (2 pax) · IDR 3,125,000/person (11+ pax)*\n\n---\n\n#### 5-Day Packages\n\n**5 Day Ijen, Papuma Beach, Tumpak Sewu & Bromo Nature Trip — Surabaya Return**\nFull East Java circuit with relaxed driving days: Ijen, Papuma Beach, Tumpak Sewu, and Bromo. Returns to Surabaya.\n*From IDR 5,050,000/person (2 pax) · IDR 3,650,000/person (11+ pax)*\n\n**5 Day Ijen, Bromo, Madakaripura & Malang City Adventure — Surabaya Return**\nVolcano circuit plus Malang city on Day 4–5 before returning to Surabaya.\n*From IDR 5,250,000/person (2 pax) · IDR 3,850,000/person (11+ pax)*\n\n---\n\n#### 6-Day Package\n\n**6 Day Ijen, Papuma Beach, Tumpak Sewu, Bromo & Malang City Discovery — Surabaya Return**\nJVTO''s widest single tour. All five East Java highlights — Ijen, Papuma, Tumpak Sewu, Bromo, Malang — over six days with realistic driving pacing.\n*From IDR 6,050,000/person (2 pax) · IDR 4,750,000/person (11+ pax)*\n\n---\n\n## What''s Included Section\n\n### Section Heading\nEvery package includes — in writing\n\nAll 11 packages include the following. No surprise local payments.\n\n- **Private transport**: AC MPV (1–3 guests) or Toyota Hiace (4–9 guests). Fuel, tolls, and parking included.\n- **Dedicated crew**: English-speaking driver-guide (1–3 guests), or professional driver + escort guide (4+ guests). Licensed local site guides at key locations.\n- **Entrance fees and permits** to all attractions on the itinerary.\n- **Accommodation + breakfast** (all overnight packages, per itinerary).\n- **Private 4WD Jeep** for Bromo crater area (Bromo-inclusive packages). One jeep per ≤4 guests; additional jeeps arranged for larger groups.\n- **Gas masks and trekking poles** (Ijen-inclusive packages).\n- **Health-certificate screening coordination** for Ijen routes for every guest under BBKSDA SE.1658/KSA.9/2024.\n- **Daily mineral water supply**.\n- **Full pick-up to drop-off assistance** from your Surabaya hotel or address.\n- **JVTO travel T-shirt** (1 per participant).\n\n**Not included**: flights, tips, personal expenses, travel insurance, Indonesian VISA (if applicable).\n\n---\n\n## Why JVTO Section\n\n### Section Heading\nThe facts behind the booking\n\n**Police-Led Operations**\nMr. Sam holds the rank of Bripka and serves as an active officer of Ditpamobvit East Java (Tourist Police). Independent national press — Detik.com, 2021-03-14 — confirms active-duty status. No other tour operator in East Java is led by a serving Tourist Police officer.\n\n**100% Private — No Shared Groups**\nYour booking receives a dedicated vehicle and crew. No join-in option exists. Group size determines vehicle type (MPV or Hiace); timing and route decisions apply to your group only.\n\n**All-Inclusive — Written Before You Book**\nInclusions and exclusions are published on every package page and confirmed in your voucher. The voucher is the booking reference. Mid-trip negotiations over ticket costs, fuel, or meals do not occur on JVTO routes.\n\n**Verifiable Credentials**\nNIB 1102230032918 is verifiable via the Indonesian OSS system. HPWKI membership is registered under AHU-0001072.AH.01.07.TAHUN 2024. BBKSDA clearance and POLPAR authorisation are on file. All guides hold KTA credentials (2024 issuance). Dr. Ahmad Irwandanu holds a valid SIP license (Kemenkes/KKI verifiable).\n\n---\n\n## Trust Signals Section\n\n### Section Heading\nCheck us before you book\n\n| Signal | Source |\n|---|---|\n| Trustpilot: 4.8/5 · 51 reviews | Independent (verified 2026-05-09) |\n| Google Maps: 4.90/5 · 123 reviews | Independent |\n| TripAdvisor: 4.95/5 · 21 reviews | Independent |\n| NIB 1102230032918 | OSS-verifiable |\n| Founder: active Tourist Police officer | Detik.com press record, 2021 |\n| ISIC Student Tours | Provider ID 259268 (isic.org verifiable) |\n| Founded: 2015 | Booking.com 2015 award, Stefan Loose 2016 p. 287 |\n\nJVTO does not ask for CVV codes, OTP codes, or online banking passwords via chat or email. Pay only via the official JVTO website, listed bank accounts, or confirmed WhatsApp +62 822 4478 8833.\n\n---\n\n## Booking Section\n\n### Section Heading\nBook direct — no agency fees\n\n1. **WhatsApp** +62 822 4478 8833 with your dates, group size, and preferred package.\n2. Receive a price confirmation (per the pricing table for your group size).\n3. Pay a 20% deposit via Xendit secure checkout (card or QRIS) to confirm the booking; if Day 1 is within 14 days, up to 100% may be required.\n4. Receive your e-voucher with full trip details and a pre-trip guide.\n\n**Deposit**: 20% of total (up to 100% if Day 1 is within 14 days), via Xendit secure checkout — card or QRIS. Wise or bank transfer for the balance.\n**Balance deadline**: card — 5 days before Day 1 · bank wire/Wise — 3 days before Day 1.\n**Cancellation ≥ 48h before Day 1**: 100% converted to Lifetime Package Credit (no expiry, transferable).\n**Cancellation < 48h before Day 1**: forfeited. No Package Credit.\n\n**Student pricing available** for verified ISIC cardholders (Provider ID 259268). Ask at booking.\n\n**Group incentive (direct bookings only)**: 18 paying guests → 1 free place · 35 paying → 2 free places · 50 paying → 3 free places + 5% group discount.\n\n---\n\n*Sources: [[products/packages-overview]] · [[products/packages-full-pricing]] · [[website/copy-bank]] · [[website/brand-voice]] · [[website/aeo-claims]] · [[credentials/trust-signals]] · [[credentials/legal-licenses]] · [[people/agung-sambuko]] · [[sources/ssot-v6]]*","schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-surabaya';
