INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 9, 'page_content', 'design-system', '{"h1":"3D2N Bromo + Ijen (Bali–Bali)","body_md":"# 3D2N Bromo + Ijen (Bali–Bali)\n\nPrivate 3D2N tour from Bali, covering mount-bromo, kawah-ijen.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,050,000 per person\n- 3 pax: IDR 3,800,000 per person\n- 4–5 pax: IDR 3,550,000 per person\n- 6–7 pax: IDR 3,350,000 per person\n- 8–10 pax: IDR 3,050,000 per person\n- 11–null pax: IDR 2,850,000 per person","faq":[],"schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-bali/bromo-ijen-3d2n';
