INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 9, 'page_content', 'design-system', '{"h1":"4D3N Ijen + Bromo + Madakaripura Expedition (Surabaya–Surabaya)","body_md":"# 4D3N Ijen + Bromo + Madakaripura Expedition (Surabaya–Surabaya)\n\nPrivate 4D3N tour from Surabaya, covering kawah-ijen, mount-bromo, madakaripura.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,450,000 per person\n- 3 pax: IDR 4,250,000 per person\n- 4–5 pax: IDR 3,950,000 per person\n- 6–7 pax: IDR 3,650,000 per person\n- 8–10 pax: IDR 3,175,000 per person\n- 11–null pax: IDR 3,025,000 per person","faq":[],"schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-surabaya/ijen-bromo-madakaripura-4d3n';
