INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 9, 'page_content', 'design-system', '{"h1":"3D2N Taman Safari Prigen + Bromo + Madakaripura (Specialty)","body_md":"# 3D2N Taman Safari Prigen + Bromo + Madakaripura (Specialty)\n\nPrivate 3D2N tour from Surabaya, covering taman-safari-prigen, mount-bromo, madakaripura.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,350,000 per person\n- 3 pax: IDR 4,150,000 per person\n- 4–5 pax: IDR 3,950,000 per person\n- 6–7 pax: IDR 3,750,000 per person\n- 8–10 pax: IDR 3,550,000 per person\n- 11–null pax: IDR 3,450,000 per person","faq":[],"schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-surabaya/taman-safari-prigen-bromo-madakaripura-3d2n';
