INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 9, 'page_content', 'design-system', '{"h1":"4D3N Tumpak Sewu + Bromo + Ijen (Surabaya–Bali overland)","body_md":"# 4D3N Tumpak Sewu + Bromo + Ijen (Surabaya–Bali overland)\n\nPrivate 4D3N tour from Surabaya, covering tumpak-sewu, mount-bromo, kawah-ijen.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,550,000 per person\n- 3 pax: IDR 4,350,000 per person\n- 4–5 pax: IDR 4,050,000 per person\n- 6–7 pax: IDR 3,750,000 per person\n- 8–10 pax: IDR 3,275,000 per person\n- 11–null pax: IDR 3,125,000 per person","faq":[],"schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/tours/from-surabaya/tumpak-sewu-bromo-ijen-4d3n';
