INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'card_grid', 'landscape', '{}'::jsonb, ARRAY['destination:mount-bromo','destination:kawah-ijen','destination:madakaripura','destination:papuma-beach','destination:tumpak-sewu']::text[], '{}'::text[] FROM pages p WHERE p.route = '/destinations';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'design-system', '{"h1":"/destinations — Hub Page Copy","body_md":"# /destinations — Hub Page Copy\n\n---\n\n## Hero\n\n**Five destinations. One licensed operator for all of them.**\n\nEvery site on JVTO''s East Java circuit — volcano craters, canyon waterfalls, a coastal headland — is reached by dedicated private vehicle, with BBKSDA park clearance already in hand.\n\n---\n\n## Destination Cards\n\n### Kawah Ijen — Ijen Crater\n\n**Elevation**: 2,386 m\n\nThe world''s highest-volume acidic crater lake sits inside an active stratovolcano in Banyuwangi. Pre-dawn, sulfuric gases ignite at the crater floor — a blue-fire phenomenon visible in suitable weather conditions. You share the trail with sulfur miners carrying 70–90 kg loads. There is no other experience like it in Java.\n\n**Slug**: `/destinations/ijen-crater`\n\n---\n\n### Mount Bromo\n\n**Elevation**: 2,329 m\n\nBromo sits inside the vast Tengger caldera — a volcanic sea of sand framed by sheer caldera walls. The Penanjakan sunrise viewpoint at 2,770 m is one of Southeast Asia''s most photographed scenes. Access is by 4WD jeep across the caldera floor at 03:00. The BBKSDA national-park clearance is already arranged.\n\n**Slug**: `/destinations/mount-bromo`\n\n---\n\n### Tumpak Sewu Waterfall\n\n**Height**: ~120 m (multi-tiered curtain)\n\nA curved cliff face in Lumajang Regency sends dozens of streams over its edge in a continuous curtain drop. Known as Java''s Niagara. Most visitors stand at the rim. Those who descend the ~300 steps into the canyon stand at the base, surrounded by mist. JVTO guides assess fitness before the descent begins — the choice to go down stays with the guest.\n\n**Slug**: `/destinations/tumpak-sewu-waterfall`\n\n---\n\n### Madakaripura Waterfall\n\n**Distinction**: Tallest waterfall in Java — main curtain drop ~100 m\n\nA narrow canyon in Probolinggo Regency walls you in for ~1.5 km before the gorge opens into a horseshoe of falling water. Bring a raincoat — the spray reaches everywhere. The site is said to be where Gajah Mada, the 14th-century Majapahit prime minister, spent his final days.\n\n**Slug**: `/destinations/madakaripura-waterfall`\n\n---\n\n### Papuma Beach\n\n**Feature**: White-sand beach + cape headland (~86 m), Jember Regency\n\nThe only coastal stop on a JVTO East Java circuit. After Ijen''s 2,386 m night hike, Papuma resets the pace — white sand, offshore rock formations, and a short headland walk rising to ~86 m with views along the coast. Positioned between the volcano hike legs and the canyon waterfall stops on Papuma-family packages.\n\n**Slug**: `/destinations/papuma-beach`\n\n---\n\n## Transport Note\n\nEvery destination on this list is reached by dedicated private vehicle — AC MPV for smaller groups, Toyota Hiace for larger ones. No public buses. No shared transfers. Your vehicle, your driver, your schedule.","schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/destinations';
