INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'rich_text', NULL, '{}'::jsonb, ARRAY['claim:c6']::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/reviews';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Guest Voices: Real Experiences, Independently Verified","faq":[{"a":"No. Reviews on independent platforms (Tripadvisor, Trustpilot, Google, ISIC, Indecon) cannot be edited or deleted by JVTO. What you see is what guests submitted.","q":"Can JVTO edit or delete reviews on Tripadvisor or Trustpilot?"},{"a":"Independent review platforms: Tripadvisor, Trustpilot, Google Maps, ISIC provider listing, and Indecon spotlight. Direct links are listed on this page.","q":"Where can I read JVTO reviews?"},{"a":"Focus on patterns: safety mindset, guide quality, how logistics were handled, and how issues were resolved when conditions changed.","q":"What should I look for when reading reviews?"},{"a":"We read feedback for patterns. If something is unclear or wrong, we fix the process and communicate it to the team. For refund or inclusion disputes, policy pages apply.","q":"How does JVTO respond to negative feedback?"},{"a":"Yes. JVTO is listed as an official ISIC provider, and student reviews are visible on the ISIC platform. Link is on this page.","q":"Are there reviews from student travellers?"}],"lede":["Reviews matter when they are independent. We link to official platform listings so you can judge patterns yourself.","JVTO cannot edit or delete reviews on these platforms.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"sections":[{"id":"where-to-check-reviews-official-links","title":"Where to check reviews (official links)","blocks":[{"type":"markdown","body_md":"- Tripadvisor: https://www.tripadvisor.com/Attraction_Review-g297715-d19983165-Reviews-Java_Volcano_Tour_Operator-Surabaya_East_Java_Java.html\n- Trustpilot: https://trustpilot.com/review/javavolcano-touroperator.com\n- ISIC (International Student Identity Card): https://www.isic.org/discounts/?providerId=259268\n- Indecon (Ecotourism): https://www.indecon.id/spotlight-networks/java-volcano-tour-operator\n- Google Maps: https://www.google.com/maps?cid=1266403973589689021"}]},{"id":"what-to-look-for-in-reviews","title":"What to look for in reviews","blocks":[{"type":"markdown","body_md":"- Safety mindset and calm decision-making.\n- Guide quality and communication.\n- Logistics: timing, pick-ups, hotel handling.\n- How issues are handled when conditions change."}]},{"id":"how-we-respond-to-feedback","title":"How we respond to feedback","blocks":[{"type":"markdown","body_md":"We read feedback for patterns. If something is unclear, we fix the process and communicate it to the team.\n\nFor rules that affect refunds, changes, or inclusions, the policy pages apply.\n\n- Booking & payment policy: /policy/booking-payment-cancellation\n- Inclusions & exclusions: /policy/inclusions-exclusions"}]}],"faq_title":"FAQ"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/reviews';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'timeline', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-story';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'rich_text', NULL, '{}'::jsonb, ARRAY['public_person_profile:agung-sambuko']::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-story';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Our Story: Roots & Continuity Since 2015","faq":[{"a":"The documented history begins in 2015 with a Booking.com Guest Review Award delivered to the current JVTO office address in Bondowoso. The Stefan Loose travel guide (2016 edition) independently names the founder as a tour operator.","q":"When did JVTO start operating?"},{"a":"Yes. The Booking.com award was shipped to Jl. Khairil Anwar No.102, Bondowoso—the same address where JVTO operates today, confirming operational continuity.","q":"Is the office address the same as in 2015?"},{"a":"All artifacts (Booking.com plaque, Stefan Loose guidebook page, founder photos, press links) are on this page and in the full Proof Library at /verify-jvto/history-artifacts.","q":"Where can I see the historical artifacts?"},{"a":"Yes. The Stefan Loose Indonesien travel guide (4th edition, 2016, page 287) explicitly names the founder Agung as operator of Ijen tours from a Bondowoso address.","q":"Was JVTO mentioned in a printed travel guide?"},{"a":"Time on the ground usually means fewer surprises, stronger local relationships, and calmer handling of real-world issues. The artifacts allow you to audit the history independently.","q":"How does operational history relate to trust?"}],"lede":["Time on the ground matters. It usually means fewer surprises, stronger local relationships, and calmer handling of real-world issues.","We keep key artifacts accessible so the journey can be audited.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"sections":[{"id":"company-bio-0","title":"Company Bio","blocks":[{"type":"markdown","body_md":"JVTO grew from a humble local guesthouse in Bondowoso into a licensed tour operator shaped by the Tourist Police experience of our founder, Mr. Sam.\n\nWe saw the gaps in safety standards first-hand and decided to build something different: private-only routes, realistic driving days, and clear written rules.\n\nToday, we act as a bridge between wild adventure and professional safety standards.\n\n---"}]},{"id":"how-we-got-here-1","title":"How We Got Here","blocks":[{"type":"markdown","body_md":"### 2015 — The Guesthouse\n\nAgung Sambuko — Mr. Sam — grew up in Bondowoso, the town closest to Kawah Ijen. In 2015 he opened the Ijen Bondowoso Homestay on Jl. Khairil Anwar No.102 (the current office address is No.102A — the ''A'' suffix was added after the PT registration in 2016), the same address where JVTO operates today. Booking.com guests rated the property 9.4 / 10 — an award that was shipped to the Bondowoso address that year.\n\nHe was already an active officer in the Indonesian National Police, assigned to Ditpamobvit — the directorate responsible for security at vital tourist objects including the Ijen Crater area. Managing the guesthouse meant he saw both sides of East Java volcano tourism: the visitor experience and the operational safety gaps.\n\n### 2016 — PT Java Volcano Rendezvous\n\nMr. Sam incorporated PT Java Volcano Rendezvous on 2016-01-01. That same year, Stefan Loose Reiseführer Indonesien (4th Edition, 2016, ISBN 9783770167654, p. 287) named \"Agung\" as the operator of the Ijen Bondowoso Homestay with tour arrangements. An independent German travel publisher — not a JVTO-authored reference — listing the same name at the same address.\n\n### 2023 — TDUP Formalization\n\nThe Tourism Business Permit (TDUP) was formalized in 2023, completing the regulatory paperwork chain. NIB 1102230032918 is the government-issued national business registration number, verifiable through Indonesia''s OSS system.\n\n---"}]},{"id":"why-private-only-2","title":"Why Private-Only","blocks":[{"type":"markdown","body_md":"The decision to operate private tours exclusively came from what Mr. Sam observed in the field: unlicensed operators running shared groups without consistent guides, no medical screening before Ijen hikes, casual attitudes toward BBKSDA permit requirements, drivers working routes they did not know.\n\nPrivate structure removes the coordination failures that come with mixed groups. Your vehicle and crew are assigned to your booking. Safety decisions are made for your group, not averaged across strangers with different fitness levels and objectives. This is the same operational logic that applies to police convoy coordination — one command authority, clear responsibility, documented route.\n\n---"}]},{"id":"the-evidence-chain-3","title":"The Evidence Chain","blocks":[{"type":"markdown","body_md":"These are third-party records that establish operational continuity at the same Bondowoso address from 2015 to today:\n\n- **Booking.com 2015 Guest Review Award** — shipped to \"Agung, Jl. Khairil Anwar No.102, Bondowoso.\" Plaque: https://javavolcano-touroperator.com/history/booking-2015-plaque.jpg · Shipping label: https://javavolcano-touroperator.com/history/booking-2015-shipping-label.jpg\n- **Stefan Loose Reiseführer Indonesien, 4th Edition, 2016, p. 287** — ISBN 9783770167654. \"Agung\" named as operator, independent German-language guidebook. Page image: https://javavolcano-touroperator.com/history/stefan-loose-ijen-bondowoso-page.png · Mr. Sam holding the book with guests: https://javavolcano-touroperator.com/history/guest-visit-ijen-bondowoso-homestay-stefan-loose-inspired.jpg\n- **Detik.com 2021-03-14** — \"Bripka Agung Sambuko\" named in Tourist Police duties at Ijen. Independent news coverage.\n- **Radar Jember 2021-03-24** — Tourist Police formation for Ijen Geopark. \"Bripka Agung Sambuko\" named.\n- **PT Java Volcano Rendezvous incorporation** — 2016-01-01. NIB 1102230032918.\n- **TDUP formalization** — 2023. Verifiable at /verify-jvto/legal.\n\nAll of this is the same person, the same location, the same operation — documented across commercial platforms, independent press, government registration, and a European travel publisher over an eleven-year span.\n\n---"}]},{"id":"trust-anchor-4","title":"Trust Anchor","blocks":[{"type":"markdown","body_md":"PT Java Volcano Rendezvous · NIB 1102230032918 · Trustpilot 4.8 / 5 (51 reviews, verified 2026-05-09)\n\n→ [Our Team](/why-jvto/our-team) | → [The JVTO Difference](/why-jvto/the-jvto-difference) | → [Verify JVTO](/verify-jvto)"}]}],"faq_title":"FAQ"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-story';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'section_head', NULL, '{"title":"The crew"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-team';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'card_grid', 'crew', '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-team';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Local Team, Daily Execution","faq":[{"a":"JVTO currently operates with 11 active crew members—a mix of guides and drivers based in East Java.","q":"How many crew members does JVTO have?"},{"a":"Most JVTO guides are English-speaking. Driver-only roles may be Indonesian-speaking, always paired with an English-speaking escort guide on multi-day routes.","q":"Do guides speak English?"},{"a":"For multi-day tours, JVTO pairs a dedicated driver (focused on safety, timing, road conditions) with an escort guide (focused on guest briefings, pace, and logistics). This reduces mistakes on long routes.","q":"What is the Dream Team pairing?"},{"a":"Yes. JVTO uses licensed local site guides at key locations (Bromo, Ijen, Tumpak Sewu) as required by park and authority regulations, in addition to the escort guide.","q":"Are guides licensed?"},{"a":"You can mention a preference when booking via official channels. Crew assignment depends on availability and route requirements. Contact us at WhatsApp +6282244788833 or hello@javavolcano-touroperator.com.","q":"Can I request a specific guide or driver?"}],"lede":["Great tours are not just itineraries. They are daily coordination: drivers, guides, timing, hotels, permits, and mountain rules.","We focus on private trips with a local East Java team so execution stays consistent.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"sections":[{"id":"guardian-mindset","title":"How To Read This Team Page","blocks":[{"type":"markdown","body_md":"Crew bios across the tourism industry default to \"friendly\", \"knowledgeable\", \"passionate\". Those words tell you nothing. JVTO frames the crew differently: as **protectors with specific training and operational accountability**, not as enjoyable company.\n\n> A JVTO guide doesn''t just walk you up the crater. They''re a HPWKI-registered member who completed BBKSDA-supervised SAR and first-aid training at Paltuding (May 2024). When Rendi held hands with guests on the steep crater descent, that''s training, not personality.\n\nThe framing principle: lead with competence, let warmth emerge from specifics. \"Safety-first\" alone is insufficient — cite the credential chain (KTA → HPWKI → BBKSDA) and let the named moments do the rest."}]},{"id":"trust-pillar-crew-mapping","title":"Which Crew Member Owns Which Trust Pillar","blocks":[{"type":"markdown","body_md":"JVTO publishes 7 trust pillars across the why-jvto, verify-jvto, and tour pages. Each pillar is anchored to a specific crew member (or set) whose lived experience and credentials carry the proof load. Use this as a reading key: when you see a pillar cited elsewhere on the site, this is who actually delivers it.\n\n| Trust Pillar | Primary crew | Key evidence |\n|---|---|---|\n| 1. Police-Led Safety (C1) | Mr. Sam (founder) | SPRIN POLPAR, Detik 2021 overnight deployment |\n| 2. Medical Precision (C4) | Dr. Irwandanu + all guides | BBKSDA SE.1658, SIP verifiable at Kemenkes |\n| 3. Local Territory Mastery (C2) | Gufron, Anjas, Rendi | KTA + geological + SAR expertise |\n| 4. Transparency & Documentation (C3, C5) | Yandi, Fredi | Review excerpts — briefings, punctuality |\n| 5. Guest Hospitality (C7) | Boy, Kiki, Taufik, Fauzi | Named in reviews, photography, warmth |\n| 6. Environmental Stewardship (C8) | All guides via INDECON | \"Local Boys\" policy, community employment |\n| 7. Credential Verification (C5, C9) | Whole crew via KTA chain | HPWKI AHU registry, BBKSDA training record |\n\nBelow: the five archetype crew whose names appear most in reviews and on tour-page evidence callouts. The archetype label is shorthand for the role they play across the operational matrix.\n\n| Crew | KTA | Archetype | Defining evidence |\n|---|---|---|---|\n| Joyo | KTA-D-2024-011 (DB 73) | Precision Professional | *\"I drive fast, but always cleanly, smoothly, and safely.\"* |\n| Yandi | KTA-D-2024-003 (DB 1) | Senior Touring Specialist | 4.94/5.0 across 17 reviews. *\"Briefed us on what to expect.\"* |\n| Fredi | KTA-D-2024-005 (DB 7) | Reliability Anchor | *\"Always on time no matter what time of the day\"* — Pooja Prakash |\n| Gufron | KTA-G-2024-001 (DB 39) | Expert Guide | Geological + photography expertise. Divya_Stri Sep 2025 review |\n| Anjas | KTA-G-2024-006 (DB 3) | Youth/Creative | 4.91/5.0 average. Astrophotography. *\"Anjas was the highlight.\"* |"}]},{"id":"meet-our-team-14-crew-members","title":"Meet Our Team","blocks":[{"type":"crew_grid","items":[{"name":"Gufron","role":"Guide","about":"I place the highest priority on safety and risk management. I have a strong intuitive sense that helps me read situations quickly. Passionate about photography and music.","phone":"+6282266696590","facebook":"https://www.facebook.com/ghufrano.septian","instagram":"https://www.instagram.com/gfranosept","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768225567764-405955176-gufron.png","highlights":["Friendly & fun","Knowledgeable guide","Great logistics"]},{"name":"Rendi","role":"Guide","about":"Love meeting people from different backgrounds and making every trip feel easy and enjoyable. Always make sure safety during the trip and make unforgettable moments.","phone":"+6285230753827","facebook":"https://www.facebook.com/share/14TiR46vXSx/","instagram":"https://www.instagram.com/rrivaldy17","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768228514527-518051332-rendi.png","highlights":["Friendly & fun","Safety-first","Great logistics"]},{"name":"Yandi","role":"Driver","about":"Love meeting people from different backgrounds and making every trip feel easy and enjoyable. Always make sure safety during the trip.","phone":"+6285330695662","facebook":"https://www.facebook.com/yendi.juned","instagram":null,"languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768270364125-144711646-yandi.png","highlights":["Friendly & fun","Great logistics","Knowledgeable guide"]},{"name":"Boy","role":"Guide","about":"I am a local resident who enjoys welcoming visitors and sharing stories about this area. Happy to help travelers explore the natural beauty and local culture.","phone":"+6282139202828","facebook":"https://www.facebook.com/muhammad.trezzakuzha","instagram":"https://www.instagram.com/trisbalii","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768228191022-893381041-boy.png","highlights":["Friendly & fun","Knowledgeable guide","Safety-first"]},{"name":"Fredi","role":"Driver","about":"Experienced Tour Driver committed to making your travels memorable. I combine safe driving skills with a friendly attitude to provide a stress-free experience.","phone":"+628233933939","facebook":"https://www.facebook.com/share/1BY73z5qs5/","instagram":"https://www.instagram.com/frdyska","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768276791622-262250680-freddy.png","highlights":["Friendly & fun","Great logistics","Always on time"]},{"name":"Anjas","role":"Guide","about":"I am a chill guy who loves brainrot memes, games, and all kinds of music. Let me show you how beautiful East Java is.","phone":"+6281332112387","facebook":null,"instagram":"https://www.instagram.com/anjasstywn","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768270423657-690185912-anjas.png","highlights":["Friendly & fun","Great logistics","Great photos"]},{"name":"Taufik","role":"Guide","about":"Reliable and organized with strong communication skills. My goal is to add value through hard work and a positive, proactive attitude.","phone":"+6283122231599","facebook":"https://www.facebook.com/share/1GGHkXSBQH/","instagram":"https://www.instagram.com/taufik_fik.21","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768228083285-919198019-taufik_1_.png","highlights":["Friendly & fun","Knowledgeable guide","Great logistics"]},{"name":"Kiki","role":"Guide","about":"\"It is He who made the earth manageable for you—so walk among its slopes and eat of His provision.\" (67:15)","phone":"+6281231981409","facebook":"https://m.facebook.com/osamu.tezuka.5243/","instagram":"https://www.instagram.com/kiki.the.explorer","languages":"English, Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768271545598-834784538-kiki.png","highlights":["Friendly & fun","Knowledgeable guide"]},{"name":"Holili","role":"Driver","about":"I am a Java Volcano driver who dedicates myself to serving all Java Volcano customers wholeheartedly.","phone":"+6282335267511","facebook":"https://www.facebook.com/hongz.sevenfoldism","instagram":"https://www.instagram.com/hongzsevenfoldism","languages":"Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768277053384-470130286-holili.jpg","highlights":["Friendly & fun","Great logistics"]},{"name":"Fauzi","role":"Guide","about":"I am a friendly guide who loves taking photos for guests and quickly connects with people. I enjoy making trips fun, relaxed, and memorable.","phone":"+6285171620319","facebook":"https://www.facebook.com/share/14TnVhvZg6Q","instagram":"https://www.instagram.com/srjdnfauzi_","languages":"Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768226003889-338819579-fauzi.png","highlights":["Friendly & fun","Great photos"]},{"name":"Joyo","role":"Driver","about":"I drive fast, but always cleanly, smoothly, and safely. Clients frequently tell me I am their number one choice because they know they will get there quickly without feeling unsafe.","phone":"+6285334116339","facebook":"https://www.facebook.com/udit.wahyudi.2025","instagram":null,"languages":"Indonesian","photo_url":"https://javavolcano-touroperator.com/uploads/1768277336049-911840775-joyo.png","highlights":["Professional driver","Clean and safe"]}]},{"type":"markdown","body_md":"Our local East Java team brings years of experience and deep knowledge of volcano logistics. Click each team member for detailed profile."}]},{"id":"dream-team-pairing-how-it-works","title":"Dream Team pairing (how it works)","blocks":[{"type":"markdown","body_md":"Many trips run smoother with a clear pairing: one person focuses on driving and timing, another focuses on guest flow and guiding.\n\nThis is not about luxury. It’s about reducing mistakes when routes are long and schedules are tight.\n\n- Driver: safe driving, timing, road conditions, vehicle readiness.\n- Escort guide: guest briefings, translations, pace, logistics coordination.\n- Local volcano guide (when required): site rules, on-trail guidance."}]},{"id":"operational-playbook-overview","title":"Operational playbook (overview)","blocks":[{"type":"markdown","body_md":"- Private tours only (no mixing groups).\n- Clear pick-up details and confirmations before travel days.\n- Hotel handling aligned to itinerary days (check-in control).\n- Early communication when conditions change.\n- Plain-language rules live in /travel-guide and /policy."}]}],"faq_title":"FAQ"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/our-team';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/community-standards';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Community Standards: Partners, Ethics & Operational Rules","faq":[{"a":"JVTO is partnered with ISIC (student identity card programme), HPWKI (local volcanic tourism industry body), and INDECON (ecotourism network). Details and proof links are on this page.","q":"What partnerships does JVTO hold?"},{"a":"Yes. Health screening is mandatory and non-negotiable for Ijen night hike routes. The system checks SpO2, blood pressure, resting heart rate, and respiratory history. No valid QR code means no access to the crater zone.","q":"Is health screening on Ijen mandatory?"},{"a":"Cancellations 48+ hours before Day 1 convert to 100% JVTO Package Credit (non-expiring, transferable). Cancellations under 48 hours are fully forfeited. Cash refunds are not available. Full policy: /policy/booking-payment-cancellation.","q":"What is the cancellation policy in brief?"},{"a":"No. JVTO runs private tours only. Your vehicle and crew are allocated exclusively for your booking.","q":"Does JVTO mix strangers into one vehicle?"},{"a":"JVTO offers student-focused pricing on selected tours for verified ISIC cardholders. Details and eligibility are at /isic/student-package.","q":"What does the ISIC partnership mean for students?"}],"lede":["Partnerships matter when they connect to real guest value: fairness, competence, and responsible travel.","This page also explains the operational standards and commitments that govern every JVTO tour—from financial fairness to mandatory health screening.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"sections":[{"id":"read-the-rulebook-before-you-book-0","title":"\"Read the Rulebook Before You Book\"","blocks":[{"type":"markdown","body_md":"JVTO publishes its rules, policies, and commitments before you pay anything. This is a deliberate choice. Guests who understand the terms before booking have better trips. Guests who discover cancellation policies at checkout do not.\n\nThis page covers what we expect of ourselves and what we ask of guests who book with us.\n\n---"}]},{"id":"written-rules-before-booking-1","title":"Written Rules Before Booking","blocks":[{"type":"markdown","body_md":"Three customer-facing policy documents are published openly at /policy:\n\n- **Booking, Payment & Cancellation Policy** (/policy/booking-payment-cancellation) — how bookings are confirmed, deposit and balance payment timelines, the 48-hour cancellation cut-off, force-majeure procedures, and the Package Credit system. No verbal promises. The Official E-Voucher / Invoice PDF is the binding document.\n\n- **Inclusions & Exclusions Policy** (/policy/inclusions-exclusions) — written list of what is covered in the price and what is not. The write-it-to-bind-it rule: if it is not on the voucher, it is not included. This policy is what makes the \"no surprise costs\" claim verifiable.\n\n- **Privacy & Data Protection Policy** (/policy/privacy) — what data we collect (contact and booking details, participant details, safety and logistics information), how it is used, and who it is shared with. Payment cards and QRIS are processed through a PCI DSS-compliant gateway (Xendit). JVTO does not store full card numbers, CVVs, or banking credentials.\n\nThe policy hierarchy: the E-Voucher takes precedence, then the Booking Policy, then the Inclusions Policy, then the Privacy Policy, then the Travel Guide. Written documents, in order, not verbal agreements.\n\n---"}]},{"id":"sulfur-miner-etiquette-ijen-routes-2","title":"Sulfur Miner Etiquette — Ijen Routes","blocks":[{"type":"markdown","body_md":"At Kawah Ijen, the trail from Paltuding to the crater rim is a shared working path. Local miners carry 70–90 kg loads of sulfur blocks from the crater floor — daily, at the same hours tourists are climbing.\n\nJVTO guides brief every Ijen-route group on this before departure:\n\n- **Do not block the path.** Miners are working, not trekking. Move to the side when a load-carrier approaches.\n- **Do not photograph a miner without their consent.** Ask first. If they say no, respect that.\n\nThis briefing is standard, not optional. The Ijen experience includes the mining operation as a human reality of the site — not a photographic attraction.\n\n---"}]},{"id":"local-boys-policy-community-employment-3","title":"Local Boys Policy — Community Employment","blocks":[{"type":"markdown","body_md":"JVTO recruits guides and drivers from local Bondowoso and Banyuwangi communities. The roster is not sourced from freelance marketplaces or external agencies.\n\nThis commitment is validated by INDECON membership — the Indonesian Ecotourism Network. INDECON listing explicitly validates JVTO''s Local Boys employment policy and confirms community-based tourism practices. Verifiable at https://www.indecon.id/spotlight-networks/java-volcano-tour-operator.\n\n14 field crew members appear in the current roster — all with names, photos, and languages listed on the team roster page.\n\n---"}]},{"id":"what-we-don-t-do-4","title":"What We Don''t Do","blocks":[{"type":"markdown","body_md":"From the customer-facing policies and operational standards documented in the wiki:\n\n- We do not collect full card numbers, CVV codes, OTP codes, or online banking passwords via chat or email. Payment is through our secure, PCI DSS-compliant gateway, Xendit.\n- We do not make verbal promises that override the written voucher. If it is not on the E-Voucher, it is not included.\n- We do not source crew from freelance marketplaces. Every guide and driver is a named, registered team member.\n- We do not guarantee natural phenomena. Blue Fire is a natural phenomenon subject to weather and gas activity. We plan around the viewing window — we do not promise outcomes that depend on volcanic gas conditions.\n- We do not operate shared groups. Every tour is private to your booking.\n\n---"}]},{"id":"trust-anchor-5","title":"Trust Anchor","blocks":[{"type":"markdown","body_md":"PT Java Volcano Rendezvous · NIB 1102230032918 · Trustpilot 4.8 / 5 (51 reviews, verified 2026-05-09)\n\n→ [Policy](/policy) | → [Our Team](/why-jvto/our-team) | → [The JVTO Difference](/why-jvto/the-jvto-difference)"}]}],"faq_title":"FAQ"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/why-jvto/community-standards';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'section_head', NULL, '{"title":"Travel Guide"}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'cta', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', '1', '{"h1":"Travel Guide – Safety, Health & Practical Information","faq":[{"a":"This is JVTO’s planning hub for safety rules, Ijen screening, closures/weather logic, packing/fitness, booking flow, and group escort context. It helps you prepare before departure.","q":"What is the Travel Guide for?"},{"a":"Your Official E-Voucher / Invoice (PDF) is the highest authority for your specific booking. If anything differs, follow the document precedence stated on this page and in the policy pack.","q":"What is the binding reference if anything differs?"},{"a":"Read /travel-guide/booking-information, then /policy/booking-payment-cancellation and /policy/inclusions-exclusions. Use /travel-guide/weather-and-closures for route uncertainty.","q":"Which pages should I read before paying?"},{"a":"Read /travel-guide/ijen-health-screening. Screening is part of Ijen night hike logistics when applicable and may be required by local rules.","q":"Where can I find the Ijen screening process?"},{"a":"Re-check /travel-guide/packing-and-fitness and /travel-guide/weather-and-closures. If you are unsure how a rule applies, verify via official channels before travel.","q":"What should I do close to departure?"}],"body_md":"# **Meta**\r\n\r\n**Title tag:** Travel Guide – Safety, Health & Practical Information | Java Volcano Tour Operator  \r\n**Meta description:** Official travel guide for private tours with Java Volcano Tour Operator (JVTO). Learn about booking, safety, Ijen health screening, weather and closures, packing, police escort for groups and ISIC student deals.\r\n\r\n## **H1**\r\n\r\n**Travel Guide – Safety, Health & Practical Information**\r\n\r\n## **Hero Intro**\r\n\r\n**Use this Travel Guide as JVTO’s official handbook for planning private tours to Mount Bromo, Kawah Ijen, and Tumpak Sewu.** Java Volcano Tour Operator (JVTO) is presented here as a licensed Indonesian inbound operator based in Bondowoso, specialising in private, all-inclusive routes to East Java’s key volcano and waterfall destinations.\r\n\r\n**Understand how JVTO handles safety, health, weather, closures, payments, and student deals before you book or travel.** This page summarises the key topics and directs you to dedicated detail pages for each subject.\r\n\r\n**Use your Official E-Voucher / Invoice and the Booking, Payment & Cancellation Policy as the final reference for legal or case-specific details.** This Travel Guide is a plain-language summary designed to help guests understand how things work, but binding terms remain in your official booking documents.\r\n\r\n### **Primary CTAs**\r\n\r\n**How to book & pay →** /travel-guide/booking-information  \r\n**Browse private tours →** /tours\r\n\r\n---\r\n\r\n## **Latest JVTO Update (Placeholder Block)**\r\n\r\n**Check this “Latest JVTO update” card for time-sensitive operational notes before departure.** This section is reserved for information your team can confirm and update routinely.\r\n\r\n**Last updated:** \\[DD Month YYYY\\]  \r\n**Bromo:** \\[short operational note – e.g., “operating normally; cold and windy conditions possible at sunrise.”\\]  \r\n**Ijen:** \\[short note – e.g., “night hikes require health screening and may be adjusted based on sulfur gas and wind.”\\]  \r\n**Tumpak Sewu:** \\[short note – e.g., “lower paths can be slippery after heavy rain; guides may change timings or access.”\\]\r\n\r\n**Review the relevant preparation pages if you are travelling soon.** Guests travelling in the next few weeks should review **Packing & Fitness**, **Safety on Tours**, and **Weather & Closures** before departure.\r\n\r\n**Only publish what you can reasonably confirm at the time of update.** Do not include rumours, assumptions, or unverified claims.\r\n\r\n---\r\n\r\n## **JVTO Operating Status (East Java Volcano Routes)**\r\n\r\n**Treat JVTO’s operating status as an operations update for JVTO routes—not a country-level travel advisory.** JVTO currently operates private, pre-booked tours on standard East Java routes, subject to weather, volcanic activity, and access regulations.\r\n\r\n**Expect tour plans to follow official sources and local access rules.** We plan and adjust tours based on official information (including MAGMA / PVMBG) and local park management.\r\n\r\n**Expect partial restrictions even when tours are running.** Some viewpoints, hiking sections, or waterfall access may be temporarily restricted even when the tour program continues.\r\n\r\n**Expect itinerary changes to follow the rules in Weather & Closures and Booking, Payment & Cancellation.** Changes are handled according to those pages and your booking documents.\r\n\r\n**Check your own government’s travel advice for country-level alerts.** Guests should consult official travel advisories issued by their own governments in addition to this guide.\r\n\r\n---\r\n\r\n## **On This Page (In-page Navigation)**\r\n\r\n**Use this section as a quick index of the key topics.**\r\n\r\n* Safety on JVTO tours  \r\n* Health & Ijen screening  \r\n* Weather, volcano alerts & closures  \r\n* Packing & fitness  \r\n* Booking, payments & Package Credit  \r\n* Traffic police escort for groups  \r\n* ISIC student deals  \r\n* Official sources & external links\r\n\r\n---\r\n\r\n## **Safety on JVTO Tours (Panel Summary)**\r\n\r\n**Expect JVTO tours to be run as private-only, pre-briefed programs with defined safety procedures.** JVTO is presented here as a licensed inbound operator led by an active Tourist Police officer in East Java, and all tours are stated to be private-only (no mixed groups, no transport-only tickets).\r\n\r\n**Expect routing and decisions to adapt to conditions and regulations.** We monitor official information on volcanic activity and weather, apply safety procedures on roads and trails, and adjust itineraries when conditions or regulations make the original plan unsafe.\r\n\r\n**CTA:** Read full safety overview → /travel-guide/safety-on-tours\r\n\r\n---\r\n\r\n## **Health & Ijen Screening (Panel Summary)**\r\n\r\n**Expect Ijen night hikes to require screening and to remain subject to safety decisions even after clearance.** Kawah Ijen is described here as a night hike at altitude with possible sulfur gas exposure.\r\n\r\n**Expect screening to be included for eligible JVTO guests and to be digitally verifiable.** For JVTO guests joining Ijen hikes, the package includes a formal health screening by trained medical staff, recorded digitally and verifiable via QR code.\r\n\r\n**Expect the public tool to exist, and expect hikes to be modified or cancelled if conditions are unsafe.** The same digital system is described as available to other travellers via a public tool. A cleared screening reduces risk but does not remove it; hikes may still be cancelled or modified based on conditions.\r\n\r\n**CTA:** Ijen health screening – what we do and why → /travel-guide/ijen-health-screening\r\n\r\n---\r\n\r\n## **Weather, Volcano Alerts & Closures (Panel Summary)**\r\n\r\n**Expect natural conditions to change access and require adjustments to plans.** Heavy rain, landslides, volcanic ash, gas, smoke, floods, forest fires, road damage, or official ceremonies can affect access to Bromo, Ijen, and Tumpak Sewu.\r\n\r\n**Expect JVTO to distinguish partial closures from full closures and propose alternatives where possible.** Some issues affect only one viewpoint or path; others trigger full closure.\r\n\r\n**Expect Package Credit options to follow the Booking Policy and your E-Voucher.** When changes are required, JVTO applies the options defined in the Booking, Payment & Cancellation Policy and your Official E-Voucher / Invoice, including Package Credit where applicable.\r\n\r\n**CTA:** How JVTO handles weather, volcano alerts and closures → /travel-guide/weather-and-closures\r\n\r\n---\r\n\r\n## **Packing & Fitness (Panel Summary)**\r\n\r\n**Expect these routes to be non-technical but physically demanding for many travellers.** Early starts, night hiking, cold winds, steep paths, stairs, and wet or slippery sections can apply across Bromo, Ijen, and Tumpak Sewu.\r\n\r\n**Expect the guide to provide self-checks and packing lists, not medical approval.** The Packing & Fitness guide explains a basic self-check, what to pack for all routes, and extra items for Bromo sunrise, Ijen night hikes, and Tumpak Sewu.\r\n\r\n**Expect final hike decisions to follow screening, on-site conditions, and safety assessments.** The guide is a preparation reference; it does not override screening or safety decisions.\r\n\r\n**CTA:** Packing list & fitness checklist → /travel-guide/packing-and-fitness\r\n\r\n---\r\n\r\n## **Booking, Payments & Package Credit (Panel Summary)**\r\n\r\n**Expect JVTO bookings to operate as private, all-inclusive tours on a pre-booked basis.** The Booking Information page explains booking requests, confirmation steps, deposits, payment timing, and methods.\r\n\r\n**Expect Package Credit to be the core cancellation mechanism rather than cash refunds.** The summary references Package Credit, how it is used, and why cash refunds are not provided, balanced by Package Credit flexibility.\r\n\r\n**Expect different time windows to affect cancellations and changes.** The page describes changes, reschedules, and cancellations across different timelines.\r\n\r\n**CTA:** Full booking, payment & Package Credit rules → /travel-guide/booking-information\r\n\r\n---\r\n\r\n## **Traffic Police Escort for Groups (Panel Summary)**\r\n\r\n**Expect escort to be considered only for larger groups and only through formal approval.** For larger groups (example: around 18 guests or more with multi-vehicle convoys), JVTO may propose requesting official traffic police escort for specific road segments.\r\n\r\n**Expect escort to be official, conditional, documented, and not automatic.** Escort is provided by the official traffic police unit, subject to law, written approval, and availability.\r\n\r\n**Expect escort to be for safe convoy movement—not to bypass rules or guarantee faster travel.** If approved, details and any charges are listed in your quotation and Official E-Voucher / Invoice.\r\n\r\n**Expect no escort unless it is explicitly written.** If escort is not stated in your booking documents, the tour should be considered to run without escort.\r\n\r\n**CTA:** How official traffic police escort works for tourist groups → /travel-guide/police-escort-for-groups\r\n\r\n---\r\n\r\n## **ISIC Student Deals (Panel Summary)**\r\n\r\n**Expect ISIC student deals to be presented as a fairness mechanism against higher foreign fees.** Through collaboration with ISIC, JVTO describes student-focused structures on selected tours for verified students.\r\n\r\n**Expect eligibility and verification details to be defined on the ISIC page.** The ISIC page explains eligible tours, how to present valid ISIC identification, and how student pricing interacts with standard booking and Package Credit rules.\r\n\r\n**CTA:** ISIC student packages → /isic/student-package\r\n\r\n---\r\n\r\n## **Official Sources & External Links (Panel Summary)**\r\n\r\n**Use official Indonesian sources and your own government’s travel advice alongside this Travel Guide.** JVTO states it monitors official Indonesian authorities for planning and adjustments.\r\n\r\n**Use MAGMA Indonesia / PVMBG for volcano and geohazard context, and VONA for advanced aviation-related notices.** Links are presented as references rather than copied content.\r\n\r\n**Use local park and government announcements for temporary closures and ceremony-related restrictions.** Access rules may change due to closures, restricted zones, and official events.\r\n\r\n**Use your own government’s travel advisory for country-level security, health, and entry requirements.** JVTO positions this guide as complementary to—not a replacement for—government advisories.\r\n\r\n---\r\n\r\n## **Document Priority Reminder (Bottom of Page)**\r\n\r\n**Treat your Official E-Voucher / Invoice as the highest authority for your specific booking.** If there is ever a difference between website wording and booking documents, the order of priority is:\r\n\r\n1. Official E-Voucher / Invoice (specific booking)  \r\n2. Booking, Payment & Cancellation Policy  \r\n3. Inclusions & Exclusions Policy  \r\n4. General website text and informal communication\r\n\r\n**Verify uncertainties via official JVTO channels before travel.** Contact JVTO using the official contact details listed on the website if you are unsure how a rule applies.\r\n\r\n---\r\n\r\n\\[Unverified\\] I cannot verify factual assertions inside the drafts (e.g., licensing status, police roles, external source descriptions). The content below is an **Answer First rewrite** of your provided text only, formatted as **paste-ready blocks per URL**.\r\n\r\n---","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'faq_list', NULL, '{}'::jsonb, ARRAY['faq:all-inclusive-clarity','faq:ijen-health-screening-coordination','faq:isic','faq:our-team-personality-economy-operational-credibility','faq:press-recognition-third-party-context','faq:private-tours-execution-control','faq:proof-first-trust-verification-layer','faq:reviews-registry-independent-validation','faq:safety-led-operations']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/faq';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'page_content', '1', '{"h1":"Frequently Asked Questions","faq":[{"a":"Use only JVTO''s official channels; JVTO never asks for full card numbers, CVV, banking passwords, or OTP codes. Book and pay only through JVTO''s official channels — the website, the official WhatsApp number, the official email, and JVTO''s listed payment links and accounts. JVTO never asks for your full card number, CVV, online banking password, or one-time codes by chat or email. If an account number, link, or contact looks different, pause and verify through an official channel.","q":"Booking Safety & Anti-Fraud"},{"a":"JVTO accepts bookings only through the official website; WhatsApp and email are for support, not for booking.","q":"How to Book"},{"a":"A 48-hour cut-off: full cancellations 48h+ before Day 1 become Lifetime Package Credit; cash refunds apply only to partial passenger cancellations. Full cancellation 48h+ before Day 1 converts the confirmed package to Lifetime Package Credit (never expires; same package, pax, and price; one transfer; not cash). Within 48h it is forfeited. Partial passenger cancellations get a cash refund of the cancelled travelers'' price (100% at 48h+, 50% within 48h). Verified flight cancellations can reactivate the package for a 50% Recovery Fee.","q":"Cancellation & Lifetime Package Credit"},{"a":"For tours that include the Ijen night hike, a health certificate is mandatory for every guest before crater entry. JVTO arranges the health screening with licensed medical staff; results are recorded digitally and verifiable by QR code. A cleared screening reduces risk but does not remove it, and hikes may still be adjusted or cancelled for safety.","q":"Ijen Health Screening"},{"a":"Kawah Ijen closes to all visitors on the first Friday of each month for the Rijik ecosystem-cleaning program; JVTO schedules tours around it so guests are unaffected. Tourism Nature Park (TWA) Kawah Ijen closes completely to all tourism and mining activity on the **first Friday of every month** (00:00–23:59 WIB) for the **Rijik** ecosystem-cleaning program, which has run since March 2019.","q":"Ijen Monthly Closure (Rijik Program)"},{"a":"JVTO tours are all-inclusive of transport, crew, entrance fees, water, and stated meals; flights, insurance, tips, and personal expenses are excluded. Every JVTO package includes private transport, a dedicated driver and guide(s), all entrance fees and permits, drinking water, full pick-up to drop-off assistance, and meals as stated (at least breakfast). Bromo tours add the private 4WD jeep; Ijen tours add gas masks and trekking poles (and health-screening coordination where BBKSDA requires it); Bali-origin tours add the ferry crossing.","q":"What''s Included"},{"a":"JVTO is an official ISIC provider offering student pricing on selected packages to verified ISIC cardholders. JVTO is an official ISIC (International Student Identity Card) provider — provider ID 259268, listed publicly on the ISIC website. Verified ISIC cardholders can receive student pricing on selected packages.","q":"ISIC Student Pricing"},{"a":"JVTO cannot guarantee weather-dependent sights such as sunrise or Ijen''s blue fire; itineraries are planned to maximise the chance. Weather-dependent sights — a clear sunrise, or Ijen''s blue fire — cannot be promised, because cloud, weather, and volcanic gas are outside any operator''s control. JVTO plans timing and routes to maximise the chance of good conditions, and may adjust timing or routing for safety.","q":"Natural Phenomena Are Not Guaranteed"},{"a":"A deposit secures the booking, with the balance due before the tour; exact amounts and deadlines are on the booking page. A deposit (standard 20% of the booking value) secures a booking, with the balance due before the tour starts; close-to-departure bookings may require fuller payment. Exact amounts, accepted methods, and deadlines are shown at checkout and on the booking information page.","q":"Payment & Deposit"},{"a":"For large groups, JVTO can coordinate an official traffic-police escort on some road segments, subject to authority approval. For large groups (typically around 18 or more travelers), JVTO can coordinate an official traffic-police escort on certain road segments where the relevant Traffic Police unit approves it. This is a coordination service subject to authority approval, not a default inclusion. See the travel-guide page for how it works and any group incentives.","q":"Police Escort for Large Groups"},{"a":"This is a private tour with your own dedicated driver and guide(s); you are never combined with another group.","q":"Private Tour Format"},{"a":"English-speaking driver/guide standard; other languages subject to confirmation","q":"Crew & Language Standard"},{"a":"We use an AC MPV for 1–3 guests and a Hiace for 4–9 guests.","q":"Vehicle by Group Size"},{"a":"Standard rooming is arranged for the group; twin, double, separate rooms, or an extra room can be requested (subject to confirmation).","q":"Standard Rooming"},{"a":"Every package includes private transport, a dedicated driver and guide(s), all entrance fees and permits, drinking water, meals as stated, and full pick-up to drop-off assistance.","q":"All-Inclusive Baseline"},{"a":"Private, dedicated vehicle for your group only.","q":"private transport (dedicated vehicle)"},{"a":"Dedicated private driver and guide(s); no shared group.","q":"dedicated private driver and guide(s)"},{"a":"All entrance fees and permits for the stated route.","q":"all entrance fees and permits"},{"a":"Drinking water provided during the tour.","q":"drinking water"},{"a":"Meals as marked in the itinerary (at least breakfast).","q":"meals as stated in the itinerary"},{"a":"Full pick-up to drop-off assistance.","q":"full pick-up to drop-off assistance"},{"a":"Private 4WD jeep for the Bromo Sea of Sand and sunrise viewpoint.","q":"Private 4WD Jeep for Bromo"},{"a":"Gas masks and trekking poles for the Ijen crater hike.","q":"Ijen Equipment (Gas Mask & Trekking Poles)"},{"a":"Coordination of the BBKSDA health screening where the authority requires it.","q":"Ijen Health-Screening Coordination"},{"a":"Ketapang–Gilimanuk ferry crossing for Bali-linked packages.","q":"East Java – Bali Ferry Crossing"},{"a":"Excluded: international/domestic flights, visas, travel insurance, tips, personal expenses.","q":"Standard Exclusions"},{"a":"Active East Java volcano known for its turquoise acidic crater lake, pre-dawn \"blue fire\", and active sulfur mining, reached by a guided night hike.","q":"Kawah Ijen"},{"a":"Java''s tallest waterfall, in a narrow Probolinggo canyon near Bromo, reached by a short gorge walk where visitors get wet from the spray.","q":"Madakaripura Waterfall"},{"a":"Active East Java volcano in the Tengger caldera \"Sea of Sand\", famous for its pre-dawn sunrise panorama reached by 4WD jeep.","q":"Mount Bromo"},{"a":"A white-sand beach with offshore rock formations and a headland viewpoint in Jember, East Java — the one coastal stop on JVTO''s volcano circuits.","q":"Papuma Beach"},{"a":"A wide multi-tiered \"curtain\" waterfall in Lumajang, East Java, often called \"Java''s Niagara\", with an easy rim viewpoint and an optional steep canyon descent.","q":"Tumpak Sewu Waterfall"},{"a":"We stage here so guests can rest and prepare before the next activity. medical check can be arranged at hotel; dinner before Ijen preparation.","q":"Why We Stay Near Ijen"},{"a":"We stage here so guests can rest and prepare before the next activity. early jeep pickup; takeaway breakfast possible.","q":"Why We Stay Near Bromo Before Sunrise"},{"a":"We stage here so guests can rest and prepare before the next activity. Artha Cottage / Lumajang area is the closest base; early morning start recommended 07:00–08:00 for waterfall access.","q":"Why We Stage Near Tumpak Sewu"},{"a":"We stage here so guests can rest and prepare before the next activity. Doho Homestay / Jember area is the closest base; Papuma best visited in morning before crowds.","q":"Papuma Staging"},{"a":"We stage here so guests can rest and prepare before the next activity. Luminor Hotel / Banyuwangi area used for Bali-origin packages; ferry from Gilimanuk requires Ferizy pre-booking.","q":"Banyuwangi Staging Before Ijen"},{"a":"We stage here so guests can rest and prepare before the next activity. Whiz Prime Malang / Holiday Inn Express Surabaya used for city stays; Malang city and Batu attractions accessible on day-use basis.","q":"Malang / Batu Staging"}],"body_md":"**Note:** This Travel Guide is for information and trip planning. For binding terms (payments, cancellations, refunds/credits), please refer to the official policies and your **Official E-Voucher / Invoice (PDF)**. If anything differs, the E-Voucher/Invoice and the Policy pages take precedence.\r\n\r\n---\r\n\r\n## A) Private Tours, Inclusions & How JVTO Works\r\n### Is JVTO a private tour or shared tour?\r\nJVTO operates **private, all-inclusive tours**. Your vehicle and crew are allocated for your booking.\r\n\r\n### What does “all-inclusive” mean for JVTO?\r\n“All-inclusive” refers to the mandatory logistics that are written in your official package details and your **Official E-Voucher / Invoice (PDF)** (transport, accommodation, tickets/permits, and specific route logistics).\r\n\r\n### Where can I see exactly what is included for my booking?\r\nYour exact inclusions are defined by:\r\n1) the official package page you booked, and\r\n2) your **Official E-Voucher / Invoice (PDF)**.\r\nIf it is not written there, it is not part of the contracted inclusions.\r\n\r\n---\r\n\r\n## B) Payments, Deposit & Confirmation\r\n### When is my booking confirmed?\r\nA booking is considered confirmed after:\r\n- payment is successfully processed, and\r\n- JVTO issues your **Official E-Voucher / Invoice (PDF)**.\r\n\r\n### How much is the deposit?\r\nStandard bookings require a **20% deposit** of the total package price.\r\n\r\n### When is full payment required?\r\nIf **Day 1 is less than 14 days** from the time of booking, JVTO may require **up to 100% full payment** at checkout.\r\n\r\n### When is the remaining balance due (if only deposit was paid)?\r\n- Card: no later than **5 calendar days before Day 1**\r\n- Bank transfer / Wise: no later than **3 calendar days before Day 1**\r\n- Cash (IDR only): by exception, only if approved in writing, settled at the JVTO office before departure on Day 1\r\n\r\n---\r\n\r\n## C) Cancellations, Package Credit & No-Show\r\n### Do you offer cash refunds?\r\nGuest-initiated cancellations are handled using **JVTO Package Credit** (not cash refunds), according to the timing rules below.\r\n\r\n### What happens if I cancel 48 hours or more before Day 1?\r\nJVTO issues **Package Credit equal to 100% of payments received** for the cancelled services.\r\n\r\n### What happens if I cancel less than 48 hours before Day 1?\r\nUp to **100% of the total package price may be forfeited**, and **no Package Credit or cash refund** is normally provided.\r\n\r\n### What is considered a no-show?\r\nNot appearing at pickup, refusing to depart after crew/vehicles are deployed, or cancelling on the same day is treated as no-show/same-day cancellation:\r\n- Up to **100% forfeiture**\r\n- No refund or Package Credit for unused services\r\n\r\n---\r\n\r\n## D) Safety, Ijen Health Screening & Volcano Closures\r\n### Is Ijen health screening mandatory?\r\nFor JVTO tours that include the Ijen night hike, a **pre-hike health screening** is included and arranged by JVTO as part of the route logistics.\r\n\r\n### What does the screening check?\r\nTypical checks include simple measurements such as **blood pressure and oxygen levels**, plus a short set of questions by trained medical staff (local guidelines).\r\n\r\n### Can blue fire and sunrise views be guaranteed?\r\nNo. Visibility depends on natural conditions and local authority access rules. JVTO will always prioritise safety and legal access requirements.\r\n\r\n### What happens if a site is closed (weather, gas, volcanic activity)?\r\nJVTO may adjust the route for safety or closure reasons. For changes/cancellation by JVTO due to force majeure, remedies follow the official policy.\r\n\r\n---\r\n\r\n## E) Groups, Students & Extras\r\n### Do you provide JVTO T-shirts?\r\nEligible packages may include JVTO branded T-shirts, and group custom T-shirts may be included for groups of ≥12 **only if written** on your package/voucher.\r\n\r\n### Do you offer police escort for large groups?\r\nPolice escort / special convoy arrangements are possible in some cases, subject to availability and regulation, and **only if explicitly included in writing** (package + voucher).\r\n\r\n---\r\n\r\n## Official References (Binding Terms)\r\n- Booking, Payment & Cancellation Policy: `/policy/booking-payment-cancellation`\r\n- Inclusions & Exclusions Policy: `/policy/inclusions-exclusions`\r\n- Privacy Policy: `/policy/privacy`","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/faq';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'callout', 'lime', '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/ijen-health-screening';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'steps', NULL, '{}'::jsonb, ARRAY['policy_document:ijen-health-screening','general_module:policy-ijen-health-screening']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/ijen-health-screening';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', '1', '{"h1":"Ijen Health Screening – Real Checks, Digital Proof","faq":[{"a":"For tours that include the Ijen night hike, a pre-hike health screening is included as part of the route logistics and may be required depending on local rules at the time of travel.","q":"Is Ijen health screening mandatory?"},{"a":"Typical checks include basic measurements such as blood pressure and oxygen level plus a short set of questions by trained medical staff, following local guidelines.","q":"What does the screening typically check?"},{"a":"If a guest is denied clearance, affected components may not operate for that person. Policy handling follows /policy/booking-payment-cancellation.","q":"What happens if someone is not cleared?"},{"a":"No. Screening reduces risk but conditions remain subject to local authority decisions, weather/visibility, and on-site safety assessments.","q":"Does screening guarantee nothing will happen?"},{"a":"If personal data is collected during screening, it is handled in line with JVTO privacy commitments and provider/authority requirements. See /policy/privacy.","q":"How is screening-related data handled?"}],"body_md":"---\nprofile: website-copy\npage: /travel-guide/ijen-health-screening\noutput_date: 2026-05-16\nstatus: reviewed\nsources: [destinations/kawah-ijen, content/faq-master, jvto-travel-guide-en, content/brand-voice, content/operational-facts, sources/bbksda-pelatihan-pemandu-2024, credentials/medical-screening, sources/ssot-image-asset-map]\nvoice: Style B\n---\n\n# Ijen Health Screening — Real Checks, Digital Proof\n\n---\n\n## What the Access Rule Is\n\nBBKSDA Jawa Timur — the government conservation agency responsible for the Kawah Ijen Natural Tourism Park — issued Surat Edaran SE.1658/KSA.9/2024 establishing health-certificate requirements for Ijen crater zone access.\n\n**A health certificate is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024.** JVTO coordinates the mandatory clinic workflow under this regulation.\n\nThe certificate requirement is regulatory, set by BBKSDA East Java. It is not unilaterally imposed by JVTO — BBKSDA sets the rule; JVTO coordinates the workflow so every crater-zone guest can satisfy it. At the crater access gate, checkpoint staff verify the QR code on the certificate. No valid QR code means no crater zone access.\n\n---\n\n## What the Screening Checks\n\nThe health screening is conducted by licensed medical staff. Vitals measured include:\n\n- SpO2 (blood oxygen saturation)\n- Blood pressure\n- Heart rate\n- Respiratory history\n\nResults are recorded digitally and generate a QR code. The QR code allows BBKSDA checkpoint staff at the crater gate to verify that a real screening was completed by a licensed provider — not a paper copy that could be forged.\n\nThe QR system is available beyond JVTO guests: participating clinics and hotels in the Ijen area can provide the same screening to non-JVTO travellers. This is not a competitive restriction — it raises the safety standard for all visitors.\n\n---\n\n## The Process — How JVTO Coordinates It\n\nFor every guest on an Ijen crater route, JVTO arranges the following mandatory sequence via the **Ijen Digital Health Security System** (https://health.mountijen.com):\n\n1. **The nurse visits your hotel** the evening before the Ijen hike — in the Bondowoso or Banyuwangi area.\n2. **Vitals are checked** at your accommodation. No travel to a clinic is required.\n3. **The digital certificate with QR code is issued** for verified guests.\n4. **At the Paltuding trailhead**, BBKSDA checkpoint staff scan the QR code before permitting crater zone access.\n\nThe entire session takes place at your hotel before departure, not on the trail.\n\n### Where screening takes place\n\nScreening can be arranged at three locations depending on your itinerary:\n\n| Facility | Location | Type |\n|---|---|---|\n| **Klinik Bakti Husada** | Bondowoso | Certified medical clinic (Kemenkes RI) — physical clinic |\n| **Puskesmas Licin** | Banyuwangi | Government health centre (Dinkes Banyuwangi) |\n| **Hotel / JVTO office session** | Your accommodation | Mobile session by Dr. Irwandanu before departure |\n\n---\n\n## The Doctor — Verifiable Credentials\n\nHealth-screening coordination at JVTO uses licensed medical staff. The supervising physician is **Dr. Ahmad Irwandanu**, holding a valid SIP (Surat Izin Praktik) issued by the Indonesian Ministry of Health (Kemenkes RI).\n\nDr. Irwandanu''s SIP is publicly verifiable at: [satusehat.kemkes.go.id/sdmk](https://satusehat.kemkes.go.id/sdmk)\n\nScreening is performed by a credentialed provider under an active government-issued licence — not a formality or a self-certification by JVTO.\n\n---\n\n## What Happens If You Are Not Cleared to Hike\n\nIf screening staff or the JVTO team advise that you should not attempt the Ijen hike, that decision is followed. The climb is cancelled for that individual, not the group. Alternatives include waiting at base camp or a safe viewpoint area at Paltuding. The screening session cost is non-refundable. The rest of the group continues.\n\nThis outcome protects the individual guest and other guests on the trail. The screening is not a barrier to tourism — it is a check that prevents sending a guest with an undetected condition into a demanding environment with sulphur gas, steep terrain, and limited evacuation options.\n\n---\n\n## Screening Does Not Guarantee a Safe Hike\n\nHealth-certificate screening is a pre-hike assessment, not a guarantee. Conditions on the mountain can still change after screening is completed. JVTO may still cancel the hike after screening if volcanic gas, weather, or BBKSDA closures make the route unsafe. The certificate is a mandatory condition of access — it does not remove the operational risks of an active volcano environment.\n\nGuests with heart, lung, or circulation conditions are advised to consult their own doctor before booking, in addition to the mandatory pre-hike screening.\n\n---\n\n## Screening Photos\n\nEvidence of the actual screening process conducted at hotels and the JVTO office:\n\n| Scene | Image |\n|---|---|\n| Blood pressure check at hotel lobby | https://javavolcano-touroperator.com/screening/ijen-screening-hotel-01.jpeg |\n| Vitals recorded at hotel table before night ascent | https://javavolcano-touroperator.com/screening/ijen-screening-hotel-02.jpg |\n| Blood pressure check at JVTO office | https://javavolcano-touroperator.com/screening/jvto-office-screening-1.JPG |\n| Oxygen saturation check at JVTO office | https://javavolcano-touroperator.com/screening/jvto-office-screening-2.jpg |\n| Sample surat sehat (health clearance) printout | https://javavolcano-touroperator.com/screening/print-surat-sehat-preview.png |\n| BBKSDA ticket terms — health certificate requirement | https://javavolcano-touroperator.com/screening/bbksda/bbksda-ticket-terms-screenshot.jpeg |\n\nSource: sources/ssot-image-asset-map `health_screening` group + `uncertain` group.\n\n---\n\n## Gas Masks — Separate from Screening\n\nGas masks are provided by JVTO as a standard inclusion on all Ijen-relevant packages. This is independent of and separate from the health-screening process. Regardless of the mandatory health screening, gas masks are standard equipment on all JVTO Ijen routes.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/ijen-health-screening';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'steps', NULL, '{}'::jsonb, ARRAY['policy_document:booking-paths','policy_document:payment-rules']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/booking-information';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'data_box', NULL, '{}'::jsonb, ARRAY['policy_document:cancellation-package-credit']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/booking-information';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', '1', '{"h1":"Booking Information – How JVTO Private Tours Work","faq":[{"a":"Choose a tour, submit lead guest details at checkout, pay the required amount (deposit or full payment), then receive your Official E-Voucher / Invoice (PDF) as formal confirmation.","q":"How does a JVTO booking work?"},{"a":"Standard deposit is 20% of the total booking value.","q":"How much is the deposit?"},{"a":"If Day 1 is within 14 days, JVTO may require up to 100% full payment at checkout.","q":"When can full payment be required at checkout?"},{"a":"By card: no later than 5 days before Day 1. By bank transfer/Wise: no later than 3 days before Day 1. Cash (IDR) is only if approved in writing and settled at the JVTO office before departure.","q":"When is the balance due if I paid deposit?"},{"a":"Guest-initiated cancellations at ≥48 hours convert 100% of payments received into JVTO Package Credit (not cash refund).","q":"What happens if I cancel 48 hours or more before Day 1?"},{"a":"Late cancellations/no-shows may be forfeited up to 100%, with no Package Credit or cash refund normally provided.","q":"What happens if I cancel less than 48 hours before Day 1 or no-show?"},{"a":"Use /policy/booking-payment-cancellation and your Official E-Voucher / Invoice (PDF). If anything differs, the voucher/policies take precedence.","q":"Where do I find the binding rules?"}],"body_md":"Everything you need to know to confirm, pay, and manage a JVTO booking. The full legal text is at [javavolcano-touroperator.com/policy/booking-payment-cancellation](https://javavolcano-touroperator.com/policy/booking-payment-cancellation). What follows is the practical summary.\n\n---\n\n## How to Book\n\nBookings are made **only on the official JVTO website** (javavolcano-touroperator.com). It is a five-step process:\n\n1. **Choose your route and dates** — browse packages on the website and select your date, origin (Surabaya or Bali), group size, and route.\n2. **Review price and add-ons** — the website shows your total, inclusions, and any add-ons before you commit.\n3. **Accept the terms and pay** — accept the Terms & Cancellation Policy and pay; a 20% deposit confirms the booking (up to 100% if Day 1 is within 14 days).\n4. **Receive your Official E-Voucher** — a PDF is issued after deposit payment. This is your booking reference and includes your full trip details and pre-trip guide.\n5. **Access My Booking Portal** — post-payment, you gain access to your personal booking dashboard using your lead traveller email.\n\n**WhatsApp (+62 822 4478 8833) and email are support-only channels** — they help you plan and answer questions before and during the tour, but they never create, confirm, modify, cancel, or transfer a booking.\n\nBooking is confirmed only when: (1) a package has been selected, (2) the required payment has been processed, and (3) the Official E-Voucher / Invoice (PDF) has been issued by JVTO.\n\n---\n\n## Payment Steps and Details\n\n**Standard deposit**: 20% of total booking value, processed through JVTO''s secure payment gateway, **Xendit** (SSL-encrypted, PCI DSS-compliant). Pay by **credit/debit card** or **QRIS** (convenient for travellers from Indonesia and other ASEAN countries where cross-border QRIS is supported).\n\n**If Day 1 is within 14 days**: up to 100% full payment may be required at the time of booking.\n\n**Balance payment deadlines**:\n- By card or QRIS (Xendit, instant): no later than 5 days before Day 1\n- By bank wire or Wise: no later than 3 days before Day 1\n- Cash at the JVTO office (IDR only): only if approved in writing (see below)\n\n**Processing fees**: the card/QRIS fee is calculated by Xendit and shown transparently at checkout before you confirm. JVTO adds no surcharge on Wise or bank transfers (your own bank''s/Wise''s sending fee applies); office cash has no processing fee.\n\n**Cash balance at the JVTO office**: a cash (IDR) balance may be settled in person at the JVTO office when you arrive, before Day 1, only if approved in writing in advance — and only if you have already converted your money to IDR yourself. JVTO does not exchange currency, does not recommend or partner with any money changer, and cannot guarantee exchange rates.\n\n**All pricing is in IDR.** Prices are quoted and invoiced in Indonesian Rupiah.\n\n**Bank transfer details** (for balance payments only):\n\n| Bank | Account name | Account number | SWIFT |\n|---|---|---|---|\n| Bank BRI | PT Java Volcano Rendezvous | 001301001779564 | BRINIDJAXXX |\n| Bank BCA | PT Java Volcano Rendezvous | 1200944352 | CENAIDJAXXX |\n\nJVTO will never ask for full card numbers, CVV codes, or banking credentials via WhatsApp, chat, or email. Payments not made through the official checkout or bank accounts listed above are not valid JVTO transactions.\n\n---\n\n## FOC Group Discount Scheme\n\nJVTO direct website bookings receive FOC (Free of Charge) incentives based on group size:\n\n| Paying guests | FOC seats | Additional discount |\n|---|---|---|\n| 18+ | 1 FOC seat | — |\n| 35+ | 2 FOC seats | — |\n| 50+ | 3 FOC seats | **+ 5% discount on total package price for the entire group** |\n\nFOC benefits apply to \"paying guests\" only and must be agreed in writing during the booking process. This scheme is not available through third-party platforms (GetYourGuide, Booking.com, etc.).\n\n---\n\n## My Booking Portal\n\nAfter payment, the lead traveller gains access to My Booking Portal using the email address provided at booking. The portal is your live record of the trip and your task management tool for the pre-tour checklist.\n\n**What the portal shows:**\n- Tour dates and package summary\n- Pick-up details and vehicle/crew assignment\n- Accommodation plan\n- Daily itinerary\n- Notes from JVTO\n- E-Voucher download link\n\n**What the portal lets you do:**\n- Submit your guest list\n- Confirm pick-up and drop-off addresses\n- Set rooming preferences\n- Note dietary requirements\n- Complete your pre-trip to-do checklist\n\nAccess My Booking Portal at [javavolcano-touroperator.com](https://javavolcano-touroperator.com) using your lead traveller email.\n\n---\n\n## Your E-Voucher — The Booking Reference\n\nThe Official E-Voucher (PDF) is issued after deposit payment. It is your primary booking reference. Keep it accessible throughout your trip — digital on your phone is sufficient for most checkpoints; a paper passport may be required at crater-access gates.\n\nThe E-Voucher shows: tour dates, package inclusions, pick-up time and location, contact details for WhatsApp and email, and payment status.\n\nIn all disputes, the E-Voucher takes precedence over verbal confirmations or informal messages. Check it when it arrives and flag any discrepancies to JVTO immediately.\n\n---\n\n## Amendments and Reschedules\n\nOne free reschedule is available if requested 48 hours or more before Day 1, subject to availability. Reschedules requested less than 48 hours before Day 1 are not permitted.\n\nSignificant route changes that alter the primary destination sequence are not available — JVTO does not offer unbundled or transport-only services.\n\n---\n\n## Cancellation and Package Credit\n\n**Full cancellation:**\n- **≥ 48 hours before Day 1**: 100% converts to Lifetime Package Credit — never cash. Non-expiring; locked to the same package, traveler count and price; cannot be split or changed to another package; transferable to another person once, with written authorisation.\n- **< 48 hours before Day 1, or a no-show**: booking forfeited up to 100%; no Package Credit is issued.\n\n**Partial cancellation** (some travelers drop while at least two paying travelers remain) — cash refund on the cancelled seats only: **100%** if ≥ 48 hours before Day 1, **50%** if < 48 hours, **0%** once the tour has started. Dropping below two paying travelers is treated as a full cancellation.\n\n**Flight disruption** — if a confirmed flight is cancelled or rescheduled by the airline and no alternative works, JVTO applies a **50% flight Recovery Fee** and converts the remainder to Lifetime Package Credit.\n\nCash refunds are not available for a **full** guest-initiated cancellation. For closures caused by volcanic activity, government restrictions, or force majeure, JVTO may offer Package Credit, alternatives, or partial cash refunds — assessed per situation.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/booking-information';
