INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'rich_text', NULL, '{}'::jsonb, ARRAY['policy_document:natural-phenomena','general_module:policy-ijen-monthly-closure']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/weather-and-closures';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', '1', '{"h1":"Weather, Volcano Alerts & Closures","faq":[{"a":"Routes may change due to volcanic activity, sulfur gas exposure levels, extreme weather/heavy rain, unsafe terrain, national park closures, or road/traffic constraints.","q":"Why can plans change?"},{"a":"No. Visibility is natural-condition dependent and cannot be guaranteed. JVTO prioritizes safety and legal access.","q":"Can blue fire or sunrise views be guaranteed?"},{"a":"JVTO may adjust timing, change viewpoints/segments, or substitute a safer alternative where feasible. Remedies follow the force majeure/change rules in /policy/booking-payment-cancellation.","q":"If a destination closes, what happens?"},{"a":"Operations depend on safety and local conditions. If conditions are unsafe, the plan may be adjusted or stopped.","q":"Do you operate during bad weather?"},{"a":"Your Official E-Voucher / Invoice (PDF) and the policy pages take precedence over non-binding summaries.","q":"What is the binding reference if there is a discrepancy?"}],"body_md":"Bromo and Ijen are active volcanoes. Tumpak Sewu and Madakaripura are canyon environments where rainfall matters. Conditions change. This page explains what we watch, how we respond, and what you can expect if your dates are affected.\n\n---\n\n## Mount Bromo — Closures & Seasonal Patterns\n\nBromo sits inside the Bromo Tengger Semeru National Park (BBTNBTS). When volcanic alert levels rise, park management or BNPB may restrict or close crater access, the caldera floor, or the national park roads. JVTO follows those instructions without exception.\n\n**Volcanic closure SOP**: If Bromo closes for volcanic activity during your booking window, JVTO activates its Plan-B framework — alternative viewpoints, rescheduled timing, or replacement destinations. Guests are briefed in advance. You will not arrive to find us improvising.\n\n**Kasada festival**: The annual Tengger Hindu ceremony at Pura Luhur Poten on the caldera floor falls on a date that varies by lunar calendar each year. During Kasada, Bromo crater access may be restricted or heavily crowded. JVTO activates its Plan-B SOP for bookings that coincide with this period. If your dates are near a Kasada window, ask us when you enquire.\n\n**Best season for Bromo**: Dry season, April–October. Pre-dawn temperatures at the Penanjakan viewpoint run 5–15°C (41–59°F). Main activities — sunrise at Penanjakan, the Sea of Sand jeep traverse, crater walk — happen in the pre-dawn window (03:00–05:00) before rain is more likely later in the day.\n\n---\n\n## Kawah Ijen — Gas Activity, Access Rules & Closures\n\nIjen is monitored by BBKSDA East Java (bbksdajatim.org) and the Indonesian volcanology authority (PVMBG/Magma Indonesia). Several types of restriction apply:\n\n**Monthly closure**: The Ijen crater is closed to visitors on the **first Friday of every month**. This is a scheduled closure, not weather-dependent. If your Ijen hike falls on the first Friday of the month, JVTO will flag this when you enquire.\n\n**Gas and safety closures**: BBKSDA issues additional closures based on volcanic gas levels and safety assessments. These are announced via bbksdajatim.org. JVTO monitors these in real time and will not send guests to a closed crater.\n\n**Blue Fire visibility**: Blue Fire is a natural phenomenon subject to weather and gas activity. It is visible pre-dawn in suitable conditions at the crater floor. JVTO designs Ijen itineraries around a midnight departure to maximise the viewing window — but we cannot promise natural phenomena. Cloud cover, gas venting direction, and wind conditions are outside our control.\n\n**Health certificate — mandatory**: A recent local health certificate is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 (cited as supporting authority). JVTO coordinates the mandatory clinic workflow before the hike. No valid QR code means no crater zone access — this is a BBKSDA checkpoint requirement, not a JVTO policy.\n\n**Best season for Ijen**: Dry season, April–October. Crater rim temperatures run 10–15°C (50–59°F) at the midnight departure window.\n\n---\n\n## Tumpak Sewu & Madakaripura — Rainfall & Canyon Conditions\n\nBoth Tumpak Sewu and Madakaripura are canyon and waterfall environments. Heavy rainfall can affect water levels, trail safety, and access.\n\n- **Tumpak Sewu**: The canyon descent uses fixed ropes and handholds on steep, wet terrain. Heavy rainfall increases slip risk on the descent. Guides assess conditions on the day; if the route is unsafe, the guide makes the call.\n- **Madakaripura**: The canyon approach requires wading through a stream. Water levels rise after heavy rain. The experience involves getting wet regardless of conditions — that is the nature of the site.\n\n**Best season for both**: Visiting during the dry season (April–October) is generally more comfortable, but these are year-round destinations. Even in the wet season, many Tumpak Sewu and Madakaripura days proceed without issue.\n\n---\n\n## Seasonal Overview — East Java\n\n| Season | Months | Notes |\n|---|---|---|\n| Dry season | April – October | Recommended for Bromo and Ijen. Clearer skies, lower rainfall, better road conditions. |\n| Wet season | November – March | Higher rainfall, possible cloud at viewpoints. Canyon destinations (Tumpak Sewu, Madakaripura) remain popular. |\n\n---\n\n## Plan-B — What JVTO Does When Conditions Change\n\nIf a key activity or destination is unavailable on your dates due to volcanic activity, official closure, or safety assessment:\n\n1. We contact you in advance — you are not surprised on the day.\n2. We explain what has changed and why.\n3. We propose reasonable alternatives: different viewpoints, adjusted timing, replacement destinations.\n4. If a key itinerary element cannot operate at all, Package Credit applies to the unused portion per your booking terms.\n\nJVTO does not bypass official restrictions. If BBKSDA, BBTNBTS, or BNPB closes a site, that closure applies to us regardless of your booking.\n\nFor the full written policy on closures, reschedules, and Package Credit, see the [Booking, Payment & Cancellation Policy](https://javavolcano-touroperator.com/policy/booking-payment-cancellation).","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/weather-and-closures';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, ARRAY['policy_document:police-escort']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/police-escort-for-groups';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'page_content', '1', '{"h1":"Traffic Police Escort for Tourist Groups in East Java","faq":[{"a":"No. Police escort arrangements are not standard and apply only when explicitly written in the official package details and your Official E-Voucher / Invoice (PDF).","q":"Is police escort included by default?"},{"a":"Escort/convoy coordination may be possible for certain large group movements or VIP arrangements, subject to regulation and operational feasibility.","q":"When can escort be considered?"},{"a":"You can ask during booking discussions. Feasibility depends on local coordination, regulation, and availability. Any inclusion must be confirmed in writing on your voucher.","q":"Can I request a police escort?"},{"a":"No guarantee is stated. Escort, when applicable, is an operational coordination element and remains subject to rules and conditions.","q":"Does an escort guarantee faster travel or special access?"},{"a":"Treat it as unverified unless it appears in your official package and Official E-Voucher / Invoice (PDF). Verify via official contacts before paying.","q":"What if someone offers escort outside official channels?"}],"body_md":"---\nprofile: website-copy\npage: /travel-guide/police-escort-for-groups\noutput_date: 2026-05-16\nstatus: reviewed\nsources: [jvto-travel-guide-en, people/agung-sambuko, credentials/police-integration, content/faq-master, content/brand-voice, jvto-policy-pack-v6, sources/ssot-image-asset-map]\nvoice: Style B\n---\n\n# Police Escort for Tourist Groups in East Java\n\n---\n\n## What a Traffic Police Escort Is\n\nA traffic police escort in East Java is a formal arrangement coordinated between JVTO and the relevant Traffic Police unit (Ditlantas). When approved, uniformed traffic police travel in official police vehicles, operating under written orders, to manage road segments on specific routes. The escort assists with road flow — particularly at high-traffic junctions and toll-road exits — for large vehicle convoys.\n\nJVTO does not provide escort vehicles itself. The escort, when it occurs, is provided by the Indonesian National Police under a formal request process.\n\n---\n\n## Who Qualifies\n\n**For large groups — typically around 18 guests or more — JVTO can coordinate an official traffic police escort on certain road segments, when approved by the relevant Traffic Police unit.**\n\nThis is the exact qualifying threshold and approved framing. Escort coordination is not available as a default inclusion for smaller groups. It is a coordination service for large vehicle convoys that meet the qualifying group size.\n\nWhether a specific route and date are approved depends on regulations, Traffic Police unit availability, and route definitions at the time of request. Approval is not guaranteed.\n\n---\n\n## How It Works Operationally\n\n1. JVTO submits a formal request to the competent Traffic Police unit, including group size, vehicle count, route, and date.\n2. The request is reviewed by the Traffic Police unit against current regulations, unit availability, and route specifications.\n3. If approved, the escort is issued with written orders (SPRIN documentation). JVTO has existing police-cooperation framework documents on file.\n4. On the day, uniformed traffic police in official vehicles accompany the convoy on designated road segments — for example, from a toll exit to Bondowoso.\n\nThe escort operates under official police authority, not JVTO instruction. It does not bypass speed limits, road rules, or normal traffic regulations. It does not represent preferential access to national parks or restricted sites.\n\n---\n\n## What the Escort Does Not Include\n\n- It is not a default inclusion — it is not part of any standard JVTO package unless written on your E-Voucher.\n- It is not a guarantee of road clearance for any segment or timeline.\n- It is not a security detail — it is traffic management coordination for convoy road segments.\n- No unofficial on-road payments are associated with a JVTO-coordinated escort. If payment is requested by anyone on the road during an escort, report it to JVTO immediately.\n\n---\n\n## How to Request\n\nIf your group meets the qualifying size (typically 18 guests or more), raise the escort request when you contact JVTO for your initial quotation. Include your group size, vehicle count, proposed route, and travel dates. JVTO will assess feasibility, submit the formal request to the Traffic Police unit if appropriate, and include escort costs in your programme and invoice if approved.\n\nEscort costs are listed explicitly in the programme and invoice — no post-booking additions.\n\nContact us via WhatsApp: +62 822 4478 8833\n\n---\n\n## Police Escort Photos\n\nVisual evidence of Traffic Police escort on actual JVTO tours:\n\n| Scene | Image |\n|---|---|\n| Escorted arrival at Bondowoso hotel — day (patrol car + officer visible) | https://javavolcano-touroperator.com/ops/jvto-police-escort-arrival-hotel-bondowoso-day.jpg |\n| Escorted arrival at Bondowoso hotel — night (same pattern, different tour) | https://javavolcano-touroperator.com/ops/jvto-police-escort-arrival-hotel-bondowoso-night.jpg |\n| Police support vehicle with group prior to tour departure | https://javavolcano-touroperator.com/ops/police-vehicle-support.jpg |\n\nDay and night escort photos demonstrate this is a recurring operational pattern, not a one-off event.\n\n---\n\n## Context: JVTO''s Relationship with the Traffic Police\n\nJVTO''s founder, Mr. Sam (Agung Sambuko), is an active officer of the Indonesian National Police — assigned to Ditpamobvit (Directorate of Vital Object Security), East Java. This gives JVTO an established institutional relationship with police coordination frameworks that most tour operators do not have. SPRIN cooperation documents are on file.\n\nThis is the operational background that makes the formal request process work — not a shortcut around regulations, but an established protocol within them.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/police-escort-for-groups';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, ARRAY['claim:c1']::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/safety-on-tours';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'page_content', '1', '{"h1":"Safety on JVTO Tours","faq":[{"a":"Safety and legal access come first. Routes and timings may be adjusted if conditions change.","q":"What is JVTO’s safety principle?"},{"a":"When Ijen is included, eligible routes typically include sulfur-rated gas masks, trekking support (as configured), and a mandatory pre-hike health screening arranged by JVTO.","q":"What safety support applies to Ijen routes?"},{"a":"Be on time for pickups, follow on-site instructions, and disclose relevant health/fitness limitations before the tour where applicable.","q":"What should guests do to support safety?"},{"a":"No. Access can change due to weather, volcanic activity, or authority closures. See /travel-guide/weather-and-closures.","q":"Are routes always accessible?"},{"a":"Binding terms follow your Official E-Voucher / Invoice (PDF) and the policy pages, per the precedence order stated in the policy pack.","q":"What if something differs from the website text?"}],"body_md":"---\n\n## Risk-Aware Planning, Not Risk Avoidance\n\nMr. Sam is a Tourist Police officer first, tour operator second. That order shapes every operational decision we make. Safety at JVTO is not a marketing position — it is a written framework applied before and during every tour. We do not remove guests from real environments; we prepare them for those environments with accurate information, trained guides, proper equipment, and written contingency procedures.\n\nGuests consistently report pre-hike safety briefings as a defining feature of the JVTO experience. That is deliberate: every activity starts with a briefing because the alternative — assuming guests know what to expect — creates the conditions for preventable incidents.\n\n---\n\n## Plan-B Framework — Written Policy, Not a Promise\n\nWhen conditions change, JVTO does not improvise. We operate a documented Plan-B framework for volcanic closures, severe weather, and access restrictions.\n\nBefore Day 1, we check road and park conditions, weather alerts, hotel and transport availability, and align with our local partners at each destination. If an alert or closure is issued — whether for volcanic activity at Bromo, gas conditions at Ijen, or flood risk at Madakaripura — we contact guests in advance, explain what has changed, and propose reasonable alternatives.\n\nDuring the tour, guides monitor weather, road conditions, crowding, and local announcements in real time. We may leave viewpoints earlier, arrive later, switch routes, or choose safer paths. If a key element of your package cannot operate — for example, if Bromo''s national park closes due to volcanic activity — the policy response is documented in your booking: guests are briefed, alternatives are offered, and Package Credit is applied to unused portions where applicable.\n\nNo guest is left without a program. That is the policy, written down.\n\n---\n\n## Safety Briefings Before Each Activity\n\nBefore every hike, canyon descent, or jeep sequence, JVTO guides conduct a safety briefing. What to expect on the terrain, where to put your feet, when to hold the rope, what the gas mask covers and what it does not cover. Reviewers across multiple platforms name individual guides by name and cite these briefings specifically — Anjas, Taufik, Rendi, Gufron, Kiki.\n\nThis pattern maps to what JVTO calls T4 in its review analysis: guests repeatedly mention feeling safe, well-informed, and prepared. The briefing is not optional and not abbreviated for speed.\n\n---\n\n## BBKSDA-Supervised Guide Training at Paltuding\n\nIjen local guides at JVTO are HPWKI-affiliated (Himpunan Pelaku Wisata Khusus Ijen). HPWKI membership means completion of BBKSDA-supervised training — government-hosted, not self-certified.\n\nIn May 2024, BBKSDA Jawa Timur ran a three-day training programme (20–22 May 2024) at Paltuding — the Ijen trailhead and visitor centre inside the park. The programme targeted 250 HPWKI-affiliated guides and covered:\n\n1. Conservation area awareness\n2. Local guide responsibilities within Kawah Ijen Natural Tourism Park\n3. SAR (Search and Rescue) techniques\n4. PPGD — Emergency Medical Response (Penanggulangan Penderita Gawat Darurat)\n\nThis is the institutional training record for the guide team at Ijen. It was documented by BBKSDA Jawa Timur, not JVTO. The scope — SAR and emergency medical response — goes beyond standard guiding and positions guides as field extensions of park management.\n\n---\n\n## Gas Masks on Ijen Routes\n\nJVTO provides professional gas masks as a standard inclusion on all Ijen-relevant packages. Sulphur dioxide concentrations at the Ijen crater floor fluctuate with gas venting, wind direction, and access-point proximity. The masks are fitted, not optional accessories, and are briefed before the crater descent begins.\n\nA spare scarf or dust mask guests bring is not a substitute for the JVTO-provided gas mask in the crater area.\n\n---\n\n## Emergency Handling\n\nFor serious medical situations on tour, JVTO guides coordinate with local clinics, evacuation services, and — where relevant — Ditpamobvit contacts in the park area. Because all tours are private, the guide and driver respond only to your group; there is no divided attention across strangers.\n\nJVTO strongly recommends that all guests carry valid travel insurance covering medical emergencies, evacuation, repatriation, trip interruption, and adventure activities including volcanic hiking and canyon descent. Insurance is not included in tour pricing.\n\nGuests under the influence of alcohol or substances may be refused participation in hikes, crater descents, or steep trails — this is a written safety policy, not a discretionary call.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/safety-on-tours';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/packing-and-fitness';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'page_content', '1', '{"h1":"Packing & Fitness for Bromo, Ijen & Tumpak Sewu","faq":[{"a":"Fitness needs vary by route and pace. Use the self-check guidance on this page and ask via official channels if you have concerns before booking.","q":"How fit do I need to be?"},{"a":"Bring warm layers for cold viewpoints, closed shoes with grip, and rain protection in wet season. Add Ijen/Tumpak Sewu items depending on your itinerary.","q":"What should I pack for volcano routes?"},{"a":"Inclusions depend on the tour package and what is written on your Official E-Voucher / Invoice (PDF). Check your tour page and /policy/inclusions-exclusions.","q":"Do you provide equipment?"},{"a":"A headlamp or reliable flashlight is recommended for the Ijen night hike. Follow instructions regarding screening and gas mask use.","q":"Do I need a headlamp for Ijen?"},{"a":"Operational instructions on your voucher and on-site safety decisions override general guidance if conditions change.","q":"What overrides general packing advice?"}],"body_md":"Good preparation is straightforward on JVTO routes. The principles are: layering for cold pre-dawn starts, grip for volcanic and canyon terrain, and waterproofing where you will get wet. Below is a destination-by-destination guide to what to bring, what the terrain demands, and what we provide.\n\n---\n\n## Mount Bromo\n\n**Fitness level**: Basic mobility. You step in and out of a 4WD jeep, walk short distances across uneven volcanic sand, and climb steps to the crater rim. No sustained uphill hiking is required. Suitable for most fitness levels, including children with basic mobility and older travellers who can handle short walks on uneven ground.\n\n**What to bring:**\n- Warm layers — temperatures at the Penanjakan viewpoint run 5–15°C (41–59°F) pre-dawn\n- Hat, gloves, and a scarf or buff\n- Comfortable closed shoes (the Sea of Sand is dusty volcanic terrain; good grip recommended)\n- A light jacket or windbreaker\n- Small daypack — main luggage stays at the hotel during the sunrise sequence\n\n**What JVTO provides:**\n- Private 4WD jeep (pre-arranged, included on all Bromo-relevant packages)\n\n---\n\n## Kawah Ijen\n\n**Fitness level**: Sustained uphill walk. The trail from Paltuding trailhead to the crater rim is approximately 3 km each way, taking around 1.5–2 hours to ascend on a steep, rocky path. Guests with heart, lung, or circulation conditions should consult their doctor before booking. This is a night hike — the midnight departure targets the Blue Fire viewing window; a pre-dawn (~03:00) departure is used if only sunrise is the target.\n\n**What to bring:**\n- Warm layers for the midnight start — crater rim temperatures run 10–15°C (50–59°F)\n- Long sleeves and full-length trousers\n- Hiking shoes with good grip (the trail is dusty on the ascent and can be slippery on descent)\n- A headlamp (JVTO provides headlamps on Ijen routes — bring your own as a backup)\n- A spare scarf or dust mask for general dust (note: this is not a substitute for the JVTO-provided gas mask in the crater area)\n\n**Silver jewellery warning**: Do not wear silver on the Ijen hike. Sulphur gases tarnish silver and the reaction may be difficult or impossible to reverse. This applies to silver rings, bracelets, necklaces, earrings, and silver-coated watches.\n\n**What JVTO provides:**\n- Professional gas mask (standard inclusion on all Ijen-relevant packages — separate from health-screening coordination)\n- Headlamps\n- Trekking poles\n\n---\n\n## Tumpak Sewu\n\n**Fitness level**: Balance and grip required. The canyon descent from the viewpoint platform to the waterfall base involves fixed ropes, wooden handholds, and steep, wet, slippery ground. There are river crossings to reach the base of the falls. This route is **not recommended** for guests with serious knee, ankle, or balance issues.\n\n**What to bring:**\n- Clothing and shoes that can get completely wet and muddy — plan for it, not against it\n- Sandals or water shoes with firm grip for river crossings (flat soles on river rocks are a slip hazard)\n- A small towel and a full change of clothes for the return journey\n- Waterproof bag or dry bag for valuables and electronics\n\n**What JVTO provides:**\n- Guided canyon descent with briefing before departure\n\n---\n\n## Madakaripura\n\n**Fitness level**: Moderate — canyon wading and uneven terrain. The approach to Madakaripura involves wading through a narrow stream with wet stones underfoot. You will get wet in the canyon. The terrain is not technically demanding, but sure footing on slippery surfaces is important.\n\n**What to bring:**\n- Waterproof bag — you will enter water and the canyon spray is heavy\n- A full change of clothes and a towel\n- Sandals or shoes that can get soaked and still grip wet rock\n- Waterproof cases or dry bags for phones and cameras\n\n**What is provided at the site:**\n- Helmets are provided at the canyon entrance by local site management (not a JVTO inclusion)\n\n---\n\n## Valuables — General Advice\n\nLeave jewellery (particularly silver, as noted above), extra cash, and valuables you cannot afford to damage or lose at the hotel when heading into volcanic or canyon environments. JVTO is not responsible for personal items lost or damaged on-site.\n\n---\n\n## What JVTO Provides Across All Relevant Routes\n\n| Item | Route |\n|---|---|\n| Gas masks | All Ijen-relevant packages |\n| Headlamps | All Ijen-relevant packages |\n| Trekking poles | All Ijen-relevant packages |\n| Private 4WD jeep | All Bromo-relevant packages |\n| Health-screening coordination | Ijen-relevant packages, for every guest under BBKSDA SE.1658/KSA.9/2024 |\n| Daily bottled mineral water | All packages |","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/travel-guide/packing-and-fitness';
