INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 2, 'cta', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/verify-jvto';
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Verify JVTO: A Proof Library You Can Check","sections":[{"id":"how-to-verify","title":"How to use this page","bullets":["1. Read the claim (one sentence).","2. Open the evidence item (document, screenshot, or external registry).","3. Check the source URL — publisher, government registry, or official platform.","4. Check the last-verified date so you know how fresh the evidence is.","5. If something is missing or unclear, contact us directly."]},{"id":"legality","link":"/verify-jvto/legal","title":"Legal & Accountability","summary":"PT registration, NIB business identity, tourism operating license (TDUP), and physical office proof.","credentials":["legal-entity","nib-registration","tdup-license","physical-office"]},{"id":"police-safety","link":"/verify-jvto/police-safety","title":"Police & Safety","summary":"Tourist Police partnership documents, SPRIN letters, Ijen health screening evidence, and doctor SIP verification.","credentials":["police-partnership","health-screening","doctor-sip-ahmad-irwandanu","bbksda-official-ticket"]},{"id":"press-recognition","link":"/verify-jvto/press-recognition","title":"Press & Recognition","summary":"Third-party press coverage from Detik.com, Radar Jember (Jawa Pos), and BBKSDA Jatim — all with context.","credentials":["detik-coverage","radarjember-coverage","bbksda-training-coverage"]},{"id":"history","link":"/verify-jvto/history-artifacts","title":"History Artifacts","summary":"Booking.com Guest Review Award 2015, Stefan Loose guidebook 2018, and founder photograph — documenting operational continuity since 2015.","credentials":["historical-recognition"]},{"id":"partners","items":[{"name":"HPWKI — Himpunan Pelaku Wisata Khusus Ijen","dimension":"Operational Competence & Safety","verify_url":"https://ahu.go.id/sabh/perkumpulan/qrcode/?kode=NjAyNDAxMjczNTEwMTM2MV8wXzA3IEZlYnJ1YXJpIDIwMjRfMjcgSmFudWFyaSAyMDI0","what_it_means":"Membership requires mandatory training in volcanic safety, gas mask usage, and emergency evacuation protocols supervised by BBKSDA East Java."},{"name":"ISIC — International Student Identity Card","dimension":"Fairness & Digital Maturity","verify_url":"https://www.isic.org/discounts/?providerId=259268","what_it_means":"JVTO is a listed provider on the ISIC global network. Student discounts are verified in real-time via the Alive Verify API to prevent fraud."},{"name":"INDECON — Indonesian Ecotourism Network","dimension":"Sustainability & Ethics","verify_url":"https://www.indecon.id/spotlight-networks/java-volcano-tour-operator","what_it_means":"Listing validates commitment to community-based tourism, waste management in national parks, and local employment."}],"title":"Partners & Memberships","paragraphs":["JVTO partnerships are explained by function, not listed as logos. Each partner adds a specific trust dimension."]},{"id":"credentials","items":[{"name":"Anjas","credential_slug":"kta-anjas"},{"name":"Taufik","credential_slug":"kta-taufik"},{"name":"Rendi","credential_slug":"kta-rendi"},{"name":"Kiki","credential_slug":"kta-kiki"},{"name":"Gufron","credential_slug":"kta-gufron"}],"title":"Guide Credentials","paragraphs":["Licensed guides hold KTA (Kartu Tanda Anggota) cards from HPWKI, confirming they have completed mandatory Ijen-specific safety training."]},{"title":"Contact before you book","bullets":["WhatsApp: +6282244788833","Email: hello@javavolcano-touroperator.com","Website: https://javavolcano-touroperator.com"]}],"cross_links":{"legal":"/verify-jvto/legal","press":"/verify-jvto/press-recognition","tours":"/tours","history":"/verify-jvto/history-artifacts","why_jvto":"/why-jvto","police_safety":"/verify-jvto/police-safety"},"intro_paragraphs":["This page organizes JVTO''s verifiable credentials by category. Each section explains what we are claiming, why it matters, and where you can verify it independently.","If anything is unclear, contact us before you book — not after.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."]}'::jsonb, '{}'::text[], '{}'::text[] FROM pages p WHERE p.route = '/verify-jvto';
